#region ---------- Datenordner neben exe bzw. Skript (Berichte, Vergleichsdatenbank, Tools, Laufzeitdaten) ----------
function Test-WritableDir([string]$Dir) {
    if (-not $Dir) { return $false }
    try {
        New-Item -ItemType Directory -Path $Dir -Force -ErrorAction Stop | Out-Null
        $probe = Join-Path $Dir ('.schreibtest_{0}.tmp' -f $PID)
        [IO.File]::WriteAllText($probe, 'x'); Remove-Item $probe -Force -ErrorAction SilentlyContinue
        return $true
    } catch { return $false }
}
function Resolve-DataDir([string]$AppDir = '') {
    # 1. Optionalen Netzwerk- / NAS-Pfad aus Netzwerk.json prüfen
    $localCfgDirs = [System.Collections.Generic.List[string]]::new()
    if ($AppDir) {
        $localCfgDirs.Add((Join-Path $AppDir 'Minibench-Daten'))
        $localCfgDirs.Add($AppDir)
    }
    if ($env:LEOSMINIBENCH_EXE) {
        try {
            $exeDir = Split-Path $env:LEOSMINIBENCH_EXE -Parent
            if ($exeDir) { $localCfgDirs.Add((Join-Path $exeDir 'Minibench-Daten')) }
        } catch { }
    }
    if ($PSScriptRoot -and $PSScriptRoot -notlike "$env:TEMP*" -and $PSScriptRoot -notlike "*\tests*") {
        $localCfgDirs.Add((Join-Path $PSScriptRoot 'Minibench-Daten'))
    }
    if ($DatenDir) {
        $localCfgDirs.Add($DatenDir.TrimEnd('\'))
    }
    try {
        $myDoc = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'Leos Minibench'
        $localCfgDirs.Add($myDoc)
    } catch { }
    try {
        $appData = Join-Path ([Environment]::GetFolderPath('ApplicationData')) 'LeosMinibench'
        $localCfgDirs.Add($appData)
    } catch { }
    if (Test-Path -LiteralPath 'Minibench-Daten') {
        try { $localCfgDirs.Add((Convert-Path 'Minibench-Daten')) } catch { }
    }

    foreach ($lcd in $localCfgDirs) {
        if (-not $lcd) { continue }
        $netCfg = Join-Path $lcd 'Netzwerk.json'
        if (Test-Path -LiteralPath $netCfg) {
            try {
                $netObj = Get-Content -LiteralPath $netCfg -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $nas = $(if ($netObj.NasPfad) { [string]$netObj.NasPfad } elseif ($netObj.NetzwerkPfad) { [string]$netObj.NetzwerkPfad } else { '' }).Trim().TrimEnd('\')
                if ($nas) {
                    if (Test-WritableDir $nas) { return $nas }
                    # Automatisch Verbindung wiederherstellen via net use falls Sitzung noch nicht aktiv ist
                    try { & net.exe use $nas /persistent:yes 2>&1 | Out-Null } catch { }
                    if (Test-WritableDir $nas) { return $nas }
                }
            } catch { }
        }
    }

    # 2. Lokale Kandidaten (USB-Stick / Übergabepfad) mit automatischem Fallback
    $cands = @()
    if ($AppDir) { $cands += (Join-Path $AppDir 'Minibench-Daten'); $cands += $AppDir }
    if ($DatenDir) { $cands += $DatenDir.TrimEnd('\') }
    if ($env:LEOSMINIBENCH_EXE) {
        try {
            $exeDir = Split-Path $env:LEOSMINIBENCH_EXE -Parent
            if ($exeDir) { $cands += (Join-Path $exeDir 'Minibench-Daten') }
        } catch { }
    }
    if ($PSScriptRoot -and $PSScriptRoot -notlike "$env:TEMP*" -and $PSScriptRoot -notlike "*\tests*") { $cands += (Join-Path $PSScriptRoot 'Minibench-Daten') }
    foreach ($c in $cands) {
        # frühere Versionen: Ordner PC-Diagnose-Daten daneben übernehmen
        $old = Join-Path (Split-Path $c -Parent) 'PC-Diagnose-Daten'
        if (-not (Test-Path -LiteralPath $c) -and (Test-Path -LiteralPath $old)) { try { Rename-Item -LiteralPath $old -NewName (Split-Path $c -Leaf) -ErrorAction Stop } catch { } }
        if (Test-WritableDir $c) { return $c }
    }
    # Notlösung bei schreibgeschütztem Speicherort (z. B. gesperrter USB-Stick): Dokumente des Benutzers
    $doc = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'Leos Minibench'
    if (Test-WritableDir $doc) { $script:DataDirFallback = $true; return $doc }
    return ''
}
$script:DataDirFallback = $false
$script:DataDir  = Resolve-DataDir
$script:DbDir    = $(if ($script:DataDir) { Join-Path $script:DataDir 'Datenbank' } else { '' })
$script:CacheDir = $(if ($script:DataDir) { Join-Path $script:DataDir 'Cache' } else { '' })
$script:CpDir    = $(if ($script:DataDir) { Join-Path (Join-Path $script:DataDir 'Laufzeit') $env:COMPUTERNAME } else { Join-Path $env:TEMP ('LeosMinibench_' + $env:COMPUTERNAME) })

function Initialize-DbDir {
    if (-not $script:DbDir) { return }
    $isNew = -not (Test-Path -LiteralPath $script:DbDir)
    if ($isNew) {
        try { New-Item -ItemType Directory -Path $script:DbDir -Force -ErrorAction Stop | Out-Null } catch { return }
    }
    $existing = @(Get-ChildItem -LiteralPath $script:DbDir -Filter '*.json' -File -ErrorAction SilentlyContinue)
    if ($existing.Count -eq 0) {
        if ($script:EmbeddedReferences) {
            foreach ($k in $script:EmbeddedReferences.Keys) {
                try {
                    $target = Join-Path $script:DbDir $k
                    [IO.File]::WriteAllText($target, $script:EmbeddedReferences[$k], (New-Object Text.UTF8Encoding($false)))
                } catch { }
            }
        }
        $existing = @(Get-ChildItem -LiteralPath $script:DbDir -Filter '*.json' -File -ErrorAction SilentlyContinue)
        if ($existing.Count -eq 0) {
            $refDirs = @(
                (Join-Path $PSScriptRoot 'Daten\Referenzen'),
                (Join-Path $PSScriptRoot 'src\Daten\Referenzen'),
                (Join-Path (Split-Path $PSScriptRoot -Parent) 'src\Daten\Referenzen')
            )
            foreach ($rd in $refDirs) {
                if (Test-Path -LiteralPath $rd) {
                    $refFiles = @(Get-ChildItem -LiteralPath $rd -Filter '*.json' -File -ErrorAction SilentlyContinue)
                    if ($refFiles.Count -gt 0) {
                        foreach ($rf in $refFiles) {
                            try { Copy-Item -LiteralPath $rf.FullName -Destination (Join-Path $script:DbDir $rf.Name) -Force -ErrorAction SilentlyContinue } catch { }
                        }
                        break
                    }
                }
            }
        }
    }
}
if ($script:DbDir) { Initialize-DbDir }

# C#-Code einmal kompilieren und als DLL im Datenordner zwischenspeichern (spart bei jedem Start einige Sekunden).
# Ab v2.6: Liegt die DLL zum Hash schon vor, wird sie ohne Schreibprobe direkt geladen (kein Schreibzugriff auf den Stick).
$script:CacheInfo = New-Object System.Collections.Generic.List[string]
function Add-CachedType([string]$Name, [string]$Code, [string[]]$References = @()) {
    $refList = [System.Collections.Generic.List[string]]::new()
    if ($References) {
        foreach ($r in $References) { if ($r -and -not $refList.Contains($r)) { $refList.Add($r) } }
    }
    if ($PSVersionTable.PSEdition -ne 'Desktop') {
        # PowerShell 7+ (.NET Core / Roslyn): Wird ReferencedAssemblies verwendet, zieht Roslyn nicht
        # automatisch den Standard-Referenzsatz heran. Alle Referenz- und Windows-Desktop-Bibliotheken ergänzen.
        $refDir = Join-Path $PSHOME 'ref'
        if (Test-Path -LiteralPath $refDir) {
            foreach ($f in (Get-ChildItem -LiteralPath $refDir -Filter '*.dll' -ErrorAction SilentlyContinue)) {
                if (-not $refList.Contains($f.FullName)) { $refList.Add($f.FullName) }
            }
        }
        $desktopDlls = @(
            'System.Windows.Forms.dll',
            'System.Windows.Forms.Primitives.dll',
            'System.Drawing.dll',
            'System.Drawing.Primitives.dll',
            'System.Drawing.Common.dll',
            'System.Private.Windows.Core.dll',
            'System.Private.Windows.GdiPlus.dll'
        )
        foreach ($dllName in $desktopDlls) {
            $fullPath = Join-Path $PSHOME $dllName
            if ((Test-Path -LiteralPath $fullPath) -and -not $refList.Contains($fullPath)) {
                $refList.Add($fullPath)
            }
        }
    }
    $sha = [Security.Cryptography.SHA256]::Create()
    $hash = -join ($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Code + ($refList -join ';') + $PSVersionTable.CLRVersion)) | Select-Object -First 6 | ForEach-Object { $_.ToString('x2') })
    # IgnoreWarnings: Windows PowerShell 5.1 wertet Compilerwarnungen sonst als Fehler (eine Warnung genügt, und alle Routinen fehlen)
    $p = @{ TypeDefinition = $Code; ErrorAction = 'Stop'; IgnoreWarnings = $true }
    if ($refList.Count) { $p.ReferencedAssemblies = $refList.ToArray() }
    if ($script:CacheDir) {
        $dll = Join-Path $script:CacheDir ('{0}-{1}.dll' -f $Name, $hash)
        if (Test-Path -LiteralPath $dll) {
            try { Add-Type -Path $dll -ErrorAction Stop; $script:CacheInfo.Add(('{0} aus dem Cache' -f $Name)); return } catch { }
        }
        if (Test-WritableDir $script:CacheDir) {
            Get-ChildItem -LiteralPath $script:CacheDir -Filter ('{0}-*.dll' -f $Name) -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
            try { Add-Type @p -OutputAssembly $dll -OutputType Library } catch { Remove-Item $dll -Force -ErrorAction SilentlyContinue }
            if (Test-Path -LiteralPath $dll) { try { Add-Type -Path $dll -ErrorAction Stop; $script:CacheInfo.Add(('{0} übersetzt und zwischengespeichert' -f $Name)); return } catch { } }
        }
    }
    Add-Type @p
    $script:CacheInfo.Add(('{0} übersetzt (ohne Cache)' -f $Name))
}

# ---------- Lokaler Arbeitsordner (ab v2.6) ----------
# Rohdaten, Konsolenprotokoll und Werkzeugausgaben sammeln sich während des Laufs im lokalen TEMP
# (%TEMP%\LeosMinibench\Lauf_<PID>) und gehen am Laufende gebündelt als Anhang.zip in den Berichtsordner.
# Ziel.txt nennt den Berichtsordner: Bricht ein Lauf ab, sichert der nächste Start die Rohdaten dorthin.
function New-RunWorkDir([string]$Target) {
    try {
        $d = Join-Path (Join-Path ([IO.Path]::GetTempPath()) 'LeosMinibench') ('Lauf_{0}' -f $PID)
        New-Item -ItemType Directory -Path (Join-Path $d 'Anhang') -Force -ErrorAction Stop | Out-Null
        [IO.File]::WriteAllText((Join-Path $d 'Ziel.txt'), [string]$Target, (New-Object Text.UTF8Encoding($false)))
        return $d
    } catch { return '' }
}

# Arbeitsordner abgebrochener Läufe (Prozess läuft nicht mehr): Rohdaten als Anhang_unterbrochen.zip in den
# Berichtsordner des abgebrochenen Laufs, danach löschen. Fehlt dieser Ordner (z. B. Stick nach dem Absturz unter
# anderem Laufwerksbuchstaben), geht das ZIP in den Berichtsordner dieses Laufs ($Fallback). Gelöscht wird nur, was
# gesichert ist oder keine Rohdaten enthält. Rückgabe: Texte für die Rückstandskontrolle.
function Restore-StaleWorkDirs([string]$Fallback = '') {
    $out = New-Object System.Collections.Generic.List[string]
    $base = Join-Path ([IO.Path]::GetTempPath()) 'LeosMinibench'
    if (-not (Test-Path -LiteralPath $base)) { return $out.ToArray() }
    foreach ($d in @(Get-ChildItem -LiteralPath $base -Directory -Filter 'Lauf_*' -ErrorAction SilentlyContinue)) {
        $id = 0
        if (-not [int]::TryParse($d.Name.Substring(5), [ref]$id) -or $id -eq $PID) { continue }
        $alive = $false
        try { $pr = Get-Process -Id $id -ErrorAction Stop; $alive = ($pr.ProcessName -match 'powershell|pwsh') } catch { }
        if ($alive) { continue }
        $msg = ''; $safe = $true
        try {
            $zf = Join-Path $d.FullName 'Ziel.txt'
            $tgt = $(if (Test-Path -LiteralPath $zf) { ([IO.File]::ReadAllText($zf)).Trim() } else { '' })
            $raw = Join-Path $d.FullName 'Anhang'
            if ((Test-Path -LiteralPath $raw) -and @(Get-ChildItem -LiteralPath $raw -Force -ErrorAction SilentlyContinue).Count) {
                $safe = $false
                $dest = $(if ($tgt -and (Test-Path -LiteralPath $tgt)) { $tgt } elseif ($Fallback -and (Test-Path -LiteralPath $Fallback)) { $Fallback } else { '' })
                if ($dest) {
                    $zip = Join-Path $dest $(if ($dest -eq $tgt) { 'Anhang_unterbrochen.zip' } else { 'Anhang_unterbrochen_{0}.zip' -f $id })
                    if (Test-Path -LiteralPath $zip) { $safe = $true }
                    else {
                        Compress-Archive -Path (Join-Path $raw '*') -DestinationPath $zip -Force -ErrorAction Stop
                        $safe = (Test-Path -LiteralPath $zip)
                        $msg = ('Rohdaten eines abgebrochenen Laufs gesichert nach {0}{1}' -f $zip, $(if ($dest -ne $tgt) { ' (ursprünglicher Berichtsordner {0} nicht erreichbar)' -f $tgt } else { '' }))
                    }
                } else { $msg = 'kein Berichtsordner erreichbar' }
            }
        } catch { $safe = $false; $msg = ('Sichern fehlgeschlagen: {0}' -f $_.Exception.Message) }
        if (-not $safe) { $out.Add(('Arbeitsordner eines abgebrochenen Laufs behalten, weil seine Rohdaten nicht gesichert sind (nicht entfernbar ohne Datenverlust): {0} ({1})' -f $d.FullName, $msg)); continue }
        try { Remove-Item -LiteralPath $d.FullName -Recurse -Force -ErrorAction Stop; $out.Add(('Arbeitsordner eines abgebrochenen Laufs entfernt: {0}{1}' -f $d.FullName, $(if ($msg) { ' (' + $msg + ')' } else { '' }))) }
        catch { $out.Add(('Arbeitsordner eines abgebrochenen Laufs nicht entfernbar: {0} ({1})' -f $d.FullName, $_.Exception.Message)) }
    }
    return $out.ToArray()
}

# Schreibzugriffe auf das Laufwerk eines Pfads (Windows-Leistungszähler, Rohwerte = Summe seit dem Systemstart).
# Gezählt wird alles, was auf dieses Laufwerk schreibt; auf einem USB-Stick ist das praktisch nur Leos Minibench.
function Get-VolumeWriteCounter([string]$Path) {
    try {
        $root = [IO.Path]::GetPathRoot($Path)
        if ($root -notmatch '^([A-Za-z]):') { return $null }
        $name = $Matches[1].ToUpperInvariant() + ':'
        $c = Get-CimInstance Win32_PerfRawData_PerfDisk_LogicalDisk -Filter ("Name='{0}'" -f $name) -ErrorAction Stop | Select-Object -First 1
        if (-not $c) { return $null }
        $art = ''; try { $art = [string](New-Object IO.DriveInfo($root)).DriveType } catch { }
        return [pscustomobject]@{ Laufwerk = $name; Vorgaenge = [double]$c.DiskWritesPersec; Bytes = [double]$c.DiskWriteBytesPersec; Art = $art; Zeit = (Get-Date) }
    } catch { return $null }
}

# Unterschied zweier Zählerstände (32-Bit-Zähler der Vorgänge laufen bei 2^32 über)
function Get-WriteDelta($Before, $After) {
    if (-not $Before -or -not $After -or $Before.Laufwerk -ne $After.Laufwerk) { return $null }
    $ops = [double]$After.Vorgaenge - [double]$Before.Vorgaenge; if ($ops -lt 0) { $ops += 4294967296 }
    $by = [double]$After.Bytes - [double]$Before.Bytes; if ($by -lt 0) { $by = 0 }
    $art = switch ([string]$After.Art) { 'Removable' { 'Wechseldatenträger (USB-Stick)' } 'Fixed' { 'fest eingebautes Laufwerk' } 'Network' { 'Netzlaufwerk' } default { [string]$After.Art } }
    return [pscustomobject]@{ Laufwerk = $After.Laufwerk; Art = $art; Vorgaenge = [long]$ops; MB = [math]::Round($by / 1MB, 1); Sekunden = [math]::Round(($After.Zeit - $Before.Zeit).TotalSeconds) }
}
#endregion


#region ---------- Datenpflege (ab v2.7): nicht vergleichbare Lasttests, unvollständige und kurze Läufe ins Archiv ----------
# Lasttestergebnisse sind erst ab dieser Version untereinander vergleichbar: v2.67 hat die CPU- und RAM-Last in einen
# eigenen Prozess verlegt und die Rechenschleife umgebaut (Sinus als Polynom, andere Rechendurchläufe, keine
# Unterbrechungen durch die Speicherbereinigung). Das Rechenwerk des Benchmarks blieb gleich, Benchmark- und
# Diagnoseläufe älterer Versionen bleiben deshalb in der Datenbank (Entscheidung vom 03.10.2026).
$script:MessreiheAb = '2.67'

# Versionsnummer als Dezimalzahl: 2.7 liegt nach 2.67 (2.70), [version] würde 2.7 vor 2.67 einordnen
function ConvertTo-VersionNumber([string]$Version) {
    $v = ([string]$Version).Trim().TrimStart('v', 'V')
    if ($v -match '^(\d+)(?:\.(\d+))?') {
        $d = 0.0
        $txt = '{0}.{1}' -f $Matches[1], $(if ($Matches[2]) { $Matches[2] } else { '0' })
        if ([double]::TryParse($txt, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { return $d }
    }
    return 0.0
}

# Ist ein Lasttest dieser Version mit heutigen Lasttests vergleichbar?
function Test-MessreiheAktuell([string]$Version) { return ((ConvertTo-VersionNumber $Version) -ge (ConvertTo-VersionNumber $script:MessreiheAb)) }

function Read-DatenpflegeJson([string]$Path) {
    try { return ([IO.File]::ReadAllText($Path, [Text.Encoding]::UTF8).TrimStart([char]0xFEFF) | ConvertFrom-Json -ErrorAction Stop) } catch { return $null }
}

# Dauer "hh:mm:ss" aus dem Lasttest-Text eines Datenbankeintrags in Sekunden (oder $null)
function Get-DatenpflegeDauer([string]$Text) {
    if ($Text -match 'Dauer (\d+):(\d\d):(\d\d)') { return ([int]$Matches[1] * 3600 + [int]$Matches[2] * 60 + [int]$Matches[3]) }
    return $null
}

# Einordnung eines Datenbankeintrags. Rückgabe: '' (behalten) oder Objekt mit Ziel (Unterordner im Archiv) und Grund.
#   Messreihe     Lauf mit Lasttest aus einer Version vor $script:MessreiheAb (Benchmark und Diagnose allein bleiben)
#   Kurz          Lasttest von Hand vorzeitig beendet und kürzer als die Hälfte der geplanten Dauer, Lauf ohne jedes
#                 Messergebnis (kein Wert, kein Lasttest) oder Funktionstest; jeweils nur, wenn keine Diagnose dabei war
# Ein Lasttest, den die Abbruchschwelle beendet hat, ist ein Befund und bleibt.
function Get-DatenpflegeEinordnung($Entry) {
    if (-not $Entry) { return $null }
    $mod = [string]$Entry.Module
    $werte = @(); if ($Entry.Werte) { $werte = @($Entry.Werte.PSObject.Properties) }
    $last = [string]$Entry.Lasttest
    $hatLast = [bool]$last -or ($mod -match 'Lasttest')
    if ($hatLast -and -not (Test-MessreiheAktuell ([string]$Entry.Version))) {
        return [pscustomobject]@{ Ziel = ('Lasttest_vor_v{0}' -f $script:MessreiheAb); Art = 'Messreihe'; Grund = ('Lasttest aus v{0}, mit Lasttests ab v{1} nicht vergleichbar' -f $Entry.Version, $script:MessreiheAb) }
    }
    $diag = ($mod -match 'Diagnose \((vollständig|schnell|benutzerdefiniert)') -or ($mod -match 'Reparatur')
    if ($diag) { return $null }
    if ($mod -match 'Diagnose \(Funktionstest\)') { return [pscustomobject]@{ Ziel = 'Kurz'; Art = 'Kurz'; Grund = 'Funktionstest (prüft nur das Skript)' } }
    if (-not $werte.Count -and -not $last -and $mod -match 'Benchmark|Lasttest') { return [pscustomobject]@{ Ziel = 'Kurz'; Art = 'Kurz'; Grund = 'Lauf ohne Messergebnis' } }
    if ($last -match 'vorzeitig beendet' -and -not $werte.Count) {
        $dauer = Get-DatenpflegeDauer $last
        $plan = @([regex]::Matches($mod, '(\d+) Min\.') | ForEach-Object { [int]$_.Groups[1].Value } | Sort-Object -Descending) | Select-Object -First 1
        if ($null -ne $dauer -and $plan -and $dauer -lt ($plan * 60 / 2)) {
            return [pscustomobject]@{ Ziel = 'Kurz'; Art = 'Kurz'; Grund = ('Lasttest nach {0} s von Hand beendet (geplant {1} Min.)' -f $dauer, $plan) }
        }
    }
    return $null
}

# Berichtsordner vollständig? (Bericht als TXT oder HTML vorhanden)
function Test-BerichtVollstaendig([string]$Dir) {
    return ((Test-Path -LiteralPath (Join-Path $Dir 'Diagnosebericht.txt')) -or (Test-Path -LiteralPath (Join-Path $Dir 'Diagnosebericht.html')))
}

# Zielpfad ohne Überschreiben: bei Namensgleichheit _2, _3 ...
function Get-DatenpflegeZiel([string]$Dir, [string]$Leaf, [switch]$Ordner) {
    $t = Join-Path $Dir $Leaf
    $n = 2
    $base = [IO.Path]::GetFileNameWithoutExtension($Leaf); $ext = [IO.Path]::GetExtension($Leaf)
    if ($Ordner) { $ext = ''; $base = $Leaf }
    while (Test-Path -LiteralPath $t) { $t = Join-Path $Dir ('{0}_{1}{2}' -f $base, $n, $ext); $n++ }
    return $t
}

# Plan und Ausführung. -NurPlan zeigt nur, was geschähe. -MindestAlterMin schützt frische Läufe (Start der Oberfläche: 60).
# -ArchivDir: Ziel (Standard: Minibench-Daten\Archiv; Bauen.cmd nimmt das Archiv des Projektordners).
# Rückgabe: Objekt mit Verschoben, Geloescht, Fehler, Zeilen (Text je Eintrag) und Kurz (eine Zeile für die Oberfläche).
function Invoke-Datenpflege {
    param([string]$DataDir = $script:DataDir, [string]$ArchivDir = '', [switch]$NurPlan, [int]$MindestAlterMin = 0)
    $res = [pscustomobject]@{ Verschoben = 0; Geloescht = 0; Fehler = 0; Zeilen = (New-Object System.Collections.Generic.List[string]); Kurz = ''; Archiv = '' }
    if (-not $DataDir -or -not (Test-Path -LiteralPath $DataDir)) { $res.Kurz = 'kein Datenordner'; return $res }
    if (-not $ArchivDir) { $ArchivDir = Join-Path $DataDir 'Archiv' }
    $res.Archiv = $ArchivDir
    $now = Get-Date
    $dbDir = Join-Path $DataDir 'Datenbank'; $repDir = Join-Path $DataDir 'Berichte'
    $plan = New-Object System.Collections.Generic.List[object]
    $add = { param($Pfad, $Unterordner, $Grund, $Art) $plan.Add([pscustomobject]@{ Pfad = $Pfad; Unterordner = $Unterordner; Grund = $Grund; Art = $Art }) }
    $alt = { param($p) try { $i = Get-Item -LiteralPath $p -Force -ErrorAction Stop; return (($now - $i.LastWriteTime).TotalMinutes -ge $MindestAlterMin) } catch { return $false } }

    # Läufe, deren Absturzanalyse noch aussteht (laufend.json), bleiben unangetastet
    $busy = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($lf in @(Get-ChildItem -LiteralPath (Join-Path $DataDir 'Laufzeit') -Filter 'laufend.json' -Recurse -File -ErrorAction SilentlyContinue)) {
        $j = Read-DatenpflegeJson $lf.FullName
        if ($j -and $j.OutputDir) { [void]$busy.Add(@(([string]$j.OutputDir).TrimEnd('\', '/') -split '[\\/]')[-1]) }
    }

    # 1. Datenbankeinträge mit ihren Berichtsordnern
    $taken = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    $keep = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($f in @(Get-ChildItem -LiteralPath $dbDir -Filter '*.json' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
        $e = Read-DatenpflegeJson $f.FullName
        if (-not $e) { continue }
        $ein = Get-DatenpflegeEinordnung $e
        # Ordner relativ zum Datenordner (Berichte\<Lauf>) oder absolut; Trenner \ oder /
        $leaf = $(if ($e.Ordner) { @(([string]$e.Ordner).TrimEnd('\', '/') -split '[\\/]')[-1] } else { '' })
        if (-not $ein) { [void]$keep.Add($f.Name); continue }
        if (($leaf -and $busy.Contains($leaf)) -or ($ein.Art -eq 'Kurz' -and -not (& $alt $f.FullName))) { [void]$keep.Add($f.Name); continue }
        & $add $f.FullName (Join-Path $ein.Ziel 'Datenbank') $ein.Grund $ein.Art
        if ($leaf) {
            $rd = Join-Path $repDir $leaf
            if (Test-Path -LiteralPath $rd -PathType Container) { & $add $rd (Join-Path $ein.Ziel 'Berichte') $ein.Grund $ein.Art; [void]$taken.Add($leaf) }
        }
    }

    # 2. Berichtsordner ohne Datenbankeintrag: ohne Bericht (abgebrochen, leer) oder Lasttest vor v2.67
    #    (Version und Module stehen im Kopf von Diagnosebericht.txt)
    foreach ($d in @(Get-ChildItem -LiteralPath $repDir -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'Vergleiche' } | Sort-Object Name)) {
        if ($taken.Contains($d.Name) -or $busy.Contains($d.Name)) { continue }
        if (Test-BerichtVollstaendig $d.FullName) {
            $kopf = ''; try { $kopf = (Get-Content -LiteralPath (Join-Path $d.FullName 'Diagnosebericht.txt') -TotalCount 8 -Encoding UTF8 -ErrorAction Stop) -join "`n" } catch { }
            if ($kopf -match 'DIAGNOSEBERICHT\s+\S+\s+v([\d.]+)') {
                $kv = $Matches[1]
                if ($kopf -match 'Module\s*:\s*.*Lasttest' -and -not (Test-MessreiheAktuell $kv)) { & $add $d.FullName (Join-Path ('Lasttest_vor_v{0}' -f $script:MessreiheAb) 'Berichte') ('Lasttest aus v{0}, mit Lasttests ab v{1} nicht vergleichbar' -f $kv, $script:MessreiheAb) 'Messreihe' }
            }
            continue
        }
        if (-not (& $alt $d.FullName)) { continue }
        $files = @(Get-ChildItem -LiteralPath $d.FullName -Recurse -File -Force -ErrorAction SilentlyContinue)
        & $add $d.FullName (Join-Path 'Unvollstaendig' 'Berichte') $(if ($files.Count) { 'Lauf ohne Bericht (abgebrochen; Teilbericht und Rohdaten bleiben im Archiv)' } else { 'leerer Berichtsordner' }) 'Unvollständig'
    }

    # 3. Systemvergleiche, deren Quellen nicht mehr in der Datenbank stehen. Ein Vergleich nennt im Fuß seine Quellen
    #    ("Leos Minibench 2.65. Quellen: a.json, b.json"). Die Referenz (Referenz.json) bleibt: sie enthält nur Benchmarkwerte.
    $vgl = Join-Path $repDir 'Vergleiche'
    foreach ($v in @(Get-ChildItem -LiteralPath $vgl -Filter '*.html' -File -ErrorAction SilentlyContinue)) {
        $txt = ''; try { $txt = [IO.File]::ReadAllText($v.FullName, [Text.Encoding]::UTF8) } catch { continue }
        $src = @(); if ($txt -match 'Quellen: ([^<]+)</footer>') { $src = @($Matches[1] -split ',\s*' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
        $out = @($src | Where-Object { $n = $_; @($plan | Where-Object { $_.Pfad -like ('*' + $n) }).Count })
        if ($out.Count) { & $add $v.FullName (Join-Path ('Lasttest_vor_v{0}' -f $script:MessreiheAb) 'Vergleiche') ('Systemvergleich mit Läufen, die ins Archiv gehen ({0})' -f ($out -join ', ')) 'Vergleich' }
    }

    # 4. Werkzeuge: Aus smartmontools braucht Leos Minibench nur smartctl.exe und dessen Laufwerksdatenbank drivedb.h.
    #    Der Rest des Pakets (smartd, Mailer, Updater, Hilfsprogramme) liegt ungenutzt im Tools-Ordner.
    $smb = Join-Path (Join-Path (Join-Path $DataDir 'Tools') 'smartmontools') 'bin'
    foreach ($x in @(Get-ChildItem -LiteralPath $smb -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin 'smartctl.exe', 'drivedb.h' })) {
        & $add $x.FullName (Join-Path (Join-Path 'Werkzeuge_unbenutzt' 'smartmontools') 'bin') 'Teil von smartmontools, den Leos Minibench nicht ausführt (gebraucht werden nur smartctl.exe und drivedb.h)' 'Werkzeug'
    }

    # 5. Ausführen
    foreach ($p in $plan) {
        $rel = $p.Pfad.Substring($DataDir.Length).TrimStart('\', '/')
        $zielDir = Join-Path $ArchivDir $p.Unterordner
        $line = ('{0} -> {1}: {2}' -f $rel, $p.Unterordner, $p.Grund)
        if ($NurPlan) { $res.Zeilen.Add('geplant: ' + $line); continue }
        try {
            New-Item -ItemType Directory -Path $zielDir -Force -ErrorAction Stop | Out-Null
            $ziel = Get-DatenpflegeZiel $zielDir (Split-Path $p.Pfad -Leaf) -Ordner:(Test-Path -LiteralPath $p.Pfad -PathType Container)
            Move-Item -LiteralPath $p.Pfad -Destination $ziel -ErrorAction Stop
            $res.Verschoben++
            $res.Zeilen.Add($line)
        } catch { $res.Fehler++; $res.Zeilen.Add(('nicht verschoben: {0} ({1})' -f $line, $_.Exception.Message)) }
    }

    # 6. Reste ohne Wert löschen: ältere Übersetzungen im Cache (sie entstehen bei Bedarf neu) und alte Stoppdateien
    if (-not $NurPlan) {
        $cache = Join-Path $DataDir 'Cache'
        $groups = @(Get-ChildItem -LiteralPath $cache -Filter 'LeosMinibench-*.dll' -File -ErrorAction SilentlyContinue | Group-Object { $_.Name -replace '-[0-9a-f]{12}\.dll$', '' })
        foreach ($g in $groups) {
            foreach ($x in @($g.Group | Sort-Object LastWriteTime -Descending | Select-Object -Skip 1)) {
                try { Remove-Item -LiteralPath $x.FullName -Force -ErrorAction Stop; $res.Geloescht++; $res.Zeilen.Add(('Cache\{0} gelöscht: ältere Übersetzung' -f $x.Name)) } catch { }
            }
        }
        foreach ($pc in @(Get-ChildItem -LiteralPath (Join-Path $DataDir 'Laufzeit') -Directory -ErrorAction SilentlyContinue)) {
            if (Test-Path -LiteralPath (Join-Path $pc.FullName 'laufend.json')) { continue }
            foreach ($s in @(Get-ChildItem -LiteralPath $pc.FullName -Filter 'sensor.stop' -File -ErrorAction SilentlyContinue | Where-Object { ($now - $_.LastWriteTime).TotalHours -ge 1 })) {
                try { Remove-Item -LiteralPath $s.FullName -Force -ErrorAction Stop; $res.Geloescht++; $res.Zeilen.Add(('Laufzeit\{0}\sensor.stop gelöscht: Rest der Live-Ansicht' -f $pc.Name)) } catch { }
            }
            if (-not @(Get-ChildItem -LiteralPath $pc.FullName -Force -ErrorAction SilentlyContinue).Count) { try { Remove-Item -LiteralPath $pc.FullName -Force -ErrorAction Stop } catch { } }
        }
    }

    # 7. Protokoll im Archiv
    if (-not $NurPlan -and ($res.Verschoben -or $res.Geloescht -or $res.Fehler)) {
        try {
            New-Item -ItemType Directory -Path $ArchivDir -Force -ErrorAction Stop | Out-Null
            $log = New-Object System.Text.StringBuilder
            [void]$log.AppendLine(('{0:yyyy-MM-dd HH:mm} Datenpflege v{1}, Datenordner {2}' -f $now, $ScriptVersion, $DataDir))
            foreach ($z in $res.Zeilen) { [void]$log.AppendLine('  ' + $z) }
            [IO.File]::AppendAllText((Join-Path $ArchivDir 'Datenpflege.log'), $log.ToString(), (New-Object Text.UTF8Encoding($true)))
        } catch { }
    }
    $nM = @($plan | Where-Object { $_.Art -eq 'Messreihe' -and $_.Pfad -like '*.json' -and $_.Pfad -like ($dbDir + '*') }).Count
    $nU = @($plan | Where-Object { $_.Art -eq 'Unvollständig' }).Count
    $nK = @($plan | Where-Object { $_.Art -eq 'Kurz' -and $_.Pfad -like ($dbDir + '*') }).Count
    $parts = @()
    if ($nM) { $parts += ('{0} {1} vor v{2}' -f $nM, $(if ($nM -eq 1) { 'Lasttest' } else { 'Lasttests' }), $script:MessreiheAb) }
    if ($nK) { $parts += ('{0} {1}' -f $nK, $(if ($nK -eq 1) { 'kurzer Lauf' } else { 'kurze Läufe' })) }
    if ($nU) { $parts += ('{0} {1}' -f $nU, $(if ($nU -eq 1) { 'unvollständiger Lauf' } else { 'unvollständige Läufe' })) }
    $nW = @($plan | Where-Object { $_.Art -eq 'Werkzeug' }).Count
    if ($nW) { $parts += ('{0} ungenutzte {1} von smartmontools' -f $nW, $(if ($nW -eq 1) { 'Datei' } else { 'Dateien' })) }
    $res.Kurz = $(if ($parts.Count) { '{0} {1}{2}' -f ($parts -join ', '), $(if ($NurPlan) { 'würden ins Archiv verschoben' } else { 'ins Archiv verschoben' }), $(if ($res.Fehler) { ', {0} nicht möglich' -f $res.Fehler } else { '' }) } else { 'nichts zu archivieren' })
    return $res
}

# Aufruf über die Befehlszeile (Bauen.cmd) oder die Oberfläche (Schaltfläche Aufräumen): -Datenpflege [-ArchivDir <Ordner>]
if ($Datenpflege) {
    $dp = Invoke-Datenpflege -DataDir $script:DataDir -ArchivDir $ArchivDir
    foreach ($z in $dp.Zeilen) { Write-Host ('  ' + $z) }
    Write-Host ('Datenpflege: {0}. Archiv: {1}' -f $dp.Kurz, $dp.Archiv)
    Send-GuiEvent 'RESULT' $dp.Kurz
    exit $(if ($dp.Fehler) { 1 } else { 0 })
}
#endregion
#region ---------- Startzeit auswerten (ab v2.6, Roadmap v2.5) ----------
# Minibench-Daten\Laufzeit\Start.log: ein Block je Start der Oberfläche (geschrieben von StartLog in Start.cs)
#   START|2026-10-02 10:15:03|2.6|Stick|E:|3420
#   PHASE|0|L|Programm gestartet
#   PHASE|180|L|Startfenster sichtbar ...
# Quelle L = LeosMinibench.exe, S = Skript, O = Oberfläche (C#). ms zählen ab dem Start des exe-Prozesses.
function ConvertFrom-StartLog([string[]]$Lines) {
    $res = New-Object System.Collections.Generic.List[object]
    $cur = $null
    foreach ($l in @($Lines)) {
        $x = ([string]$l).Trim() -split '\|'
        if ($x[0] -eq 'START' -and $x.Count -ge 6) {
            $ms = 0; [void][int]::TryParse($x[5], [ref]$ms)
            $cur = [pscustomobject]@{ Zeit = $x[1]; Version = $x[2]; Ort = $x[3]; Laufwerk = $x[4]; GesamtMs = $ms; Phasen = (New-Object System.Collections.Generic.List[object]) }
            $res.Add($cur)
        }
        elseif ($x[0] -eq 'PHASE' -and $x.Count -ge 4 -and $cur) {
            $ms = 0; [void][int]::TryParse($x[1], [ref]$ms)
            $cur.Phasen.Add([pscustomobject]@{ Ms = $ms; Quelle = $x[2]; Text = (($x[3..($x.Count - 1)]) -join '|') })
        }
    }
    return $res.ToArray()
}

# eigener Median: dieser Teil läuft vor dem Grundgerüst (Sondermodus -StartAuswertung)
function Get-StartMedian($Values) {
    $v = @($Values | Where-Object { $null -ne $_ } | ForEach-Object { [double]$_ } | Sort-Object)
    if (-not $v.Count) { return $null }
    if ($v.Count % 2) { return $v[[int][math]::Floor($v.Count / 2)] }
    return ($v[$v.Count / 2 - 1] + $v[$v.Count / 2]) / 2
}

# Phasenname ohne wechselnde Zusätze (Cache-Hinweis, Ort des Entpackens), damit gleiche Phasen zusammenfallen
function Get-StartPhaseKey([string]$Text) { return (([string]$Text) -replace '\s*\(.*\)\s*$', '').Trim() }

# Auswertung je Ort (Stick, Festplatte): Zahl der Starts, Median bis zur bedienbaren Oberfläche, je Phase der Median
# des Zeitpunkts und der Dauer seit der vorigen Phase. Rückgabe: Objekte für Tabellen und Tests.
function Get-StartAnalysis($Starts) {
    $out = @()
    foreach ($g in @($Starts | Group-Object Ort)) {
        $runs = @($g.Group)
        $phases = [ordered]@{}
        foreach ($r in $runs) {
            $prev = 0
            foreach ($p in $r.Phasen) {
                $k = Get-StartPhaseKey $p.Text
                if (-not $phases.Contains($k)) { $phases[$k] = [pscustomobject]@{ Phase = $k; Quelle = $p.Quelle; Zeitpunkte = (New-Object System.Collections.Generic.List[double]); Dauern = (New-Object System.Collections.Generic.List[double]) } }
                $phases[$k].Zeitpunkte.Add([double]$p.Ms); $phases[$k].Dauern.Add([double]($p.Ms - $prev)); $prev = $p.Ms
            }
        }
        $tot = @($runs | ForEach-Object { [double]$_.GesamtMs })
        $out += [pscustomobject]@{
            Ort = $g.Name; Starts = $runs.Count; MedianMs = (Get-StartMedian $tot); MinMs = (($tot | Measure-Object -Minimum).Minimum); MaxMs = (($tot | Measure-Object -Maximum).Maximum)
            Versionen = (@($runs | ForEach-Object { $_.Version } | Select-Object -Unique) -join ', ')
            Phasen = @($phases.Values | ForEach-Object { [pscustomobject]@{ Phase = $_.Phase; Quelle = $_.Quelle; ZeitpunktMs = (Get-StartMedian $_.Zeitpunkte); DauerMs = (Get-StartMedian $_.Dauern) } })
        }
    }
    return $out
}

function Format-StartAnalysis($Analysis) {
    $l = New-Object System.Collections.Generic.List[string]
    $inv = [Globalization.CultureInfo]::GetCultureInfo('de-DE')
    foreach ($a in @($Analysis)) {
        $l.Add(('Start von {0}: {1} Start(s), Version {2}, bis zur bedienbaren Oberfläche Median {3} s (min {4} s, max {5} s)' -f $a.Ort, $a.Starts, $a.Versionen, ([double]$a.MedianMs / 1000).ToString('0.00', $inv), ([double]$a.MinMs / 1000).ToString('0.00', $inv), ([double]$a.MaxMs / 1000).ToString('0.00', $inv)))
        $l.Add(('  {0,-48} {1,10} {2,10}' -f 'Phase', 'ab Start', 'Dauer'))
        foreach ($p in $a.Phasen) {
            $l.Add(('  {0,-48} {1,10} {2,10}' -f ('{0} ({1})' -f $p.Phase, $(switch ($p.Quelle) { 'L' { 'exe' } 'S' { 'Skript' } 'O' { 'Oberfläche' } default { $p.Quelle } })), ('{0} s' -f ([double]$p.ZeitpunktMs / 1000).ToString('0.00', $inv)), ('{0} s' -f ([double]$p.DauerMs / 1000).ToString('0.00', $inv))))
        }
        $l.Add('')
    }
    if (-not $l.Count) { $l.Add('Noch keine Starts protokolliert (Start.log entsteht beim Start über LeosMinibench.exe ab Version 2.6).') }
    return $l.ToArray()
}

# Sondermodus -StartAuswertung: Auswertung von Start.log ausgeben und als Startauswertung.txt ablegen
if ($StartAuswertung) {
    $sl = $(if ($script:DataDir) { Join-Path (Join-Path $script:DataDir 'Laufzeit') 'Start.log' } else { '' })
    $lines = @(if ($sl -and (Test-Path -LiteralPath $sl)) { Get-Content -LiteralPath $sl -Encoding UTF8 })
    $txt = Format-StartAnalysis (Get-StartAnalysis (ConvertFrom-StartLog $lines))
    foreach ($t in $txt) { Write-Host $t }
    if ($sl) { try { [IO.File]::WriteAllLines((Join-Path (Split-Path $sl -Parent) 'Startauswertung.txt'), $txt, (New-Object Text.UTF8Encoding($true))) } catch { } }
    exit 0
}
#endregion
#region ---------- Risikostufen ----------
# Jeder Schritt eines Moduls hat eine Risikostufe. Sie bestimmt, welche Absicherung vor der Ausführung nötig ist:
#   Lesen        verändert nichts am System
#   Aendern      verändert Einstellungen; jede Änderung landet mit Vorher-Wert im Änderungsprotokoll und lässt sich rückgängig machen
#   Eingriff     verändert das System dauerhaft ohne automatisches Rückgängig; Wiederherstellungspunkt vorab, oft Neustart
#   Zerstoerend  vernichtet Daten; nur nach eigener Bestätigung mit der Seriennummer des Ziels
$script:RiskOrder  = @('Lesen', 'Aendern', 'Eingriff', 'Zerstoerend')
$script:RiskLabels = @{ Lesen = 'Lesen'; Aendern = 'Ändern'; Eingriff = 'Eingriff'; Zerstoerend = 'Zerstörend' }

function Get-RiskRank([string]$Level) {
    $i = [array]::IndexOf($script:RiskOrder, [string]$Level)
    if ($i -lt 0) { throw ('Unbekannte Risikostufe: {0}' -f $Level) }
    return $i
}

function Get-RiskLabel([string]$Level) {
    if ($script:RiskLabels.ContainsKey([string]$Level)) { return $script:RiskLabels[[string]$Level] }
    return [string]$Level
}

# Höchste Stufe aus einer Liste; leere Liste ergibt Lesen
function Get-MaxRisk($Levels) {
    $max = 0
    foreach ($l in @($Levels)) { if ($l) { $r = Get-RiskRank $l; if ($r -gt $max) { $max = $r } } }
    return $script:RiskOrder[$max]
}

# Seriennummern vergleichen, ohne dass Leerzeichen, Bindestriche oder Groß- und Kleinschreibung stören
function ConvertTo-SerialKey([string]$Serial) { return (([string]$Serial) -replace '[\s\-_.]', '').ToUpperInvariant() }

# Freigabe für zerstörende Schritte: Die eingegebene Seriennummer muss vollständig zum Ziel passen.
# Platzhalter wie "Default string" oder leere Seriennummern werden nie akzeptiert, weil sie das Ziel nicht eindeutig benennen.
function Test-DestructiveConfirmation {
    param([string]$ExpectedSerial, [string]$GivenSerial)
    $exp = ConvertTo-SerialKey $ExpectedSerial
    $giv = ConvertTo-SerialKey $GivenSerial
    if ($exp.Length -lt 4 -or $exp -match '^(0+|F+|DEFAULTSTRING|TOBEFILLEDBYOEM|SYSTEMSERIALNUMBER|NONE|NA|UNKNOWN)$') { return $false }
    return ($exp -ceq $giv)
}

# Prüft vor einem Schritt, ob die Absicherung seiner Stufe vorhanden ist. Rückgabe: leer = darf laufen, sonst Begründung.
function Get-RiskBlocker {
    # Eingriff ohne Wiederherstellungspunkt bleibt erlaubt (Schalter -OhneWiederherstellungspunkt), der Bericht vermerkt es.
    param([string]$Level, [string]$ExpectedSerial = '', [string]$GivenSerial = '', [bool]$SystemDisk = $false)
    if ((Get-RiskRank $Level) -eq 3) {
        if ($SystemDisk) { return 'Das Systemlaufwerk des laufenden Windows ist für zerstörende Schritte gesperrt.' }
        if (-not (Test-DestructiveConfirmation $ExpectedSerial $GivenSerial)) { return 'Die eingegebene Seriennummer passt nicht zum gewählten Ziel.' }
    }
    return ''
}
#endregion
#region ---------- Modulvertrag ----------
# Jedes Modul beschreibt sich in src\Module\<Name>\Vertrag.psd1. Bauen.cmd bindet die Verträge hier ein.
#
#   Vertrag          Version des Vertragsformats (derzeit 1)
#   Name             Modulname, zugleich Wert für -Module
#   Seite            Titel und Kurzbeschreibung in der Navigation der Oberfläche
#   Admin            braucht Administratorrechte
#   Risiko           höchste Risikostufe, die das Modul erreichen kann (Lesen, Aendern, Eingriff, Zerstoerend)
#   Neustart         nie, moeglich oder immer (höchster Bedarf unter den Schritten)
#   Parameter        Skriptparameter, die zum Modul gehören
#   Datenbankfelder  Felder, die das Modul in den Datenbankeintrag schreibt
#   Schritte         Key, Typ, Titel, Risiko, Neustart, Rueckgaengig (keins, Protokoll, Wiederherstellungspunkt, Hinweis)
#                    Maßnahmen der Reparatur zusätzlich: Text, Minuten, Vorauswahl, Ueblich (für die Seite Reparatur)
#                    ab v2.6 (schneller Modus): Parallel ($true = darf im Hintergrund neben anderen Prüfungen laufen, nur Lesen),
#                    Nach (Keys, die vorher fertig sein müssen), Exklusiv ($true = Messung, nie neben Hintergrundaufgaben)
#
# Die @@-Zeilen zwischen Arbeitsprozess und Oberfläche bleiben das Protokoll; der Vertrag beschreibt nur, was ein Modul ist.
$script:ModuleContracts = @(
# Modulvertrag Diagnose (Vertrag 1). Felder sind in src\Kern\Modulvertrag.ps1 beschrieben.
@{
    Vertrag         = 1
    Name            = 'Diagnose'
    Seite           = @{ Titel = 'Diagnose'; Kurz = 'Inventar, Prüfungen, Ereignisse' }
    Admin           = $true
    Risiko          = 'Eingriff'
    Neustart        = 'immer'
    Parameter       = @('DiagProfil', 'DiagOptionen', 'AnalyzeLastRun', 'InstallSmartmontools', 'ScheduleWindowsMemTest', 'EventDays', 'RamTestPercent', 'RamTestPasses', 'SmartTimeoutMinutes', 'SchnellerModus')
    Datenbankfelder = @('System', 'Hardware', 'Befunde', 'Akku')
    # Ab v2.6 (schneller Modus): Parallel = darf als Hintergrundaufgabe neben anderen Prüfungen laufen, Nach = Schritte, die
    # vorher fertig sein müssen, Exklusiv = Messung, vor der alle Hintergrundaufgaben abgeschlossen sein müssen
    Schritte        = @(
        @{ Key = 'Ereignisse';     Typ = 'Pruefung'; Titel = 'Ereignisprotokolle und Absturzanalyse';  Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins' }
        @{ Key = 'Updatesuche';    Typ = 'Pruefung'; Titel = 'Suche nach ausstehenden Updates';         Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Parallel = $true }
        @{ Key = 'Integritaet';    Typ = 'Pruefung'; Titel = 'Dateisystem und Systemdateien (nur prüfen)'; Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins' }
        @{ Key = 'Defender';       Typ = 'Pruefung'; Titel = 'Defender Schnellscan';                    Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Parallel = $true }
        @{ Key = 'SmartLang';      Typ = 'Pruefung'; Titel = 'SMART-Langtest';                          Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Parallel = $true }
        @{ Key = 'Netzwerk';       Typ = 'Pruefung'; Titel = 'Netzwerktest';                            Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        @{ Key = 'RamTest';        Typ = 'Pruefung'; Titel = 'RAM-Mustertest';                          Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        # CPU-Stabilität (CpuTest) ab v2.7 entfernt: das Modul Lasttest prüft die CPU gründlicher (eigener Prozess, Drosselnachweis)
        # die Energieanalyse soll den Virenscan nicht mitmessen
        @{ Key = 'Energieanalyse'; Typ = 'Pruefung'; Titel = 'Energieanalyse und DxDiag';               Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Parallel = $true; Nach = @('Defender') }
        # Zusatzoptionen der Seite Diagnose
        @{ Key = 'Speicherdiagnose';   Typ = 'Option'; Titel = 'Windows-Speicherdiagnose beim nächsten Neustart'; Risiko = 'Lesen';    Neustart = 'immer'; Rueckgaengig = 'keins'; Schalter = 'ScheduleWindowsMemTest' }
        @{ Key = 'SmartmontoolsHolen'; Typ = 'Option'; Titel = 'smartmontools per winget holen (danach entfernen oder auf Wunsch behalten)'; Risiko = 'Eingriff'; Neustart = 'nie'; Rueckgaengig = 'keins'; Schalter = 'InstallSmartmontools' }
    )
}
# Modulvertrag Benchmark (Vertrag 1). Felder sind in src\Kern\Modulvertrag.ps1 beschrieben.
@{
    Vertrag         = 1
    Name            = 'Benchmark'
    Seite           = @{ Titel = 'Benchmark'; Kurz = 'Wählbare Messungen mit Vergleich' }
    Admin           = $true
    Risiko          = 'Aendern'
    Neustart        = 'nie'
    Parameter       = @('BenchTests', 'BenchLaufwerke', 'BenchmarkKurz', 'ReferenzSpeichern', 'ReferenzDatei', 'VergleichDateien', 'KeineDatenbank', 'BenchGpuWahl')
    Datenbankfelder = @('Werte', 'Messwerte', 'Messdauer', 'Laufwerke', 'Rendertest')
    Schritte        = @(
        @{ Key = 'CPU';    Typ = 'Messung'; Titel = 'Prozessor';             Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        @{ Key = 'RAM';    Typ = 'Messung'; Titel = 'Arbeitsspeicher';       Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        # ab v2.6 mit Rendertest (Direct3D 11) je Grafikeinheit, nacheinander
        @{ Key = 'GPU';    Typ = 'Messung'; Titel = 'Grafik';                Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        # Testdatei LeosMinibench-Benchmark.tmp wird nach der Messung gelöscht, die Rückstandskontrolle prüft das
        @{ Key = 'Disk';   Typ = 'Messung'; Titel = 'Laufwerke';             Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        # WinSAT schreibt nur in den eigenen Datenspeicher von Windows
        @{ Key = 'WinSAT'; Typ = 'Messung'; Titel = 'WinSAT-Bewertung';      Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        # Hybridgrafik: GPU-Wahl für winsat.exe (HKCU\Software\Microsoft\DirectX\UserGpuPreferences) für eine zweite Messung,
        # protokolliert und direkt danach zurückgesetzt
        @{ Key = 'GpuWahl'; Typ = 'Option'; Titel = 'Grafikkarte zusätzlich messen (Hybridgrafik)'; Risiko = 'Aendern'; Neustart = 'nie'; Rueckgaengig = 'Protokoll'; Schalter = 'BenchGpuWahl' }
    )
}
# Modulvertrag Lasttest (Vertrag 1). Felder sind in src\Kern\Modulvertrag.ps1 beschrieben.
@{
    Vertrag         = 1
    Name            = 'Lasttest'
    Seite           = @{ Titel = 'Lasttest'; Kurz = 'Komponenten und Dauer wählbar' }
    Admin           = $true
    Risiko          = 'Lesen'
    Neustart        = 'nie'
    Parameter       = @('LastCpuMinuten', 'LastRamMinuten', 'LastGpuMinuten', 'LastDiskMinuten', 'LastRamProzent', 'LastDiskLaufwerk', 'LastAbbruchCpu', 'LastAbbruchGpu')
    Datenbankfelder = @('Lasttest')
    Schritte        = @(
        @{ Key = 'CPU';  Typ = 'Last'; Titel = 'CPU';         Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
        @{ Key = 'RAM';  Typ = 'Last'; Titel = 'RAM';         Risiko = 'Lesen'; Neustart = 'nie'; Rueckgaengig = 'keins'; Exklusiv = $true }
