function Read-JsonFile([string]$Path) {
    try { return (Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { return $null }
}

function ConvertTo-ValueTable($Obj) {
    $w = @{}
    if ($Obj) { foreach ($p in $Obj.PSObject.Properties) { try { $w[$p.Name] = [double]$p.Value } catch { } } }
    return $w
}

# Alle Systeme der Vergleichsdatenbank (Format 1 und 2; Format 2 trägt die Geräteidentität)
function Get-DbEntries {
    $list = [System.Collections.Generic.List[object]]::new()
    if (-not $script:DbDir -or -not (Test-Path $script:DbDir)) { return @() }
    foreach ($f in Get-ChildItem -LiteralPath $script:DbDir -Filter '*.json' -File -ErrorAction SilentlyContinue) {
        $j = Read-JsonFile $f.FullName
        if (-not $j) { continue }
        $list.Add([pscustomobject]@{
            Path = $f.FullName; Name = [string]$j.Name; Computer = [string]$j.Computer; Datum = [string]$j.Datum
            Werte = (ConvertTo-ValueTable $j.Werte); Messwerte = (ConvertTo-ValueTable $j.Messwerte); Messdauer = [string]$j.Messdauer
            Hardware = $j.Hardware; Befunde = $j.Befunde; Laufwerke = @($j.Laufwerke); Ordner = [string]$j.Ordner
            Format = [string]$j.Format; GeraetId = $(if ($j.Geraet) { [string]$j.Geraet.Id } else { '' }); Version = [string]$j.Version; Quelle = [string]$j.Quelle
        })
    }
    Set-DbDeviceKeys $list
    return $list.ToArray()
}

# Je Gerät nur der neueste Eintrag mit Messwerten; -ExcludeCurrent lässt das Gerät dieses Laufs weg
function Get-DbLatest($Entries, [switch]$ExcludeCurrent) {
    $dev = $(if ($ExcludeCurrent) { (Get-DeviceIdentity).Id } else { '' })
    @($Entries | Where-Object { $_.Werte.Count -and $_.Computer -and -not ($ExcludeCurrent -and (Test-SameDevice $_ $dev $env:COMPUTERNAME)) } | Group-Object GeraetKey |
        ForEach-Object { $_.Group | Sort-Object Datum -Descending | Select-Object -First 1 })
}

# Kleinere Werte sind besser (Latenzen)
function Test-LowerBetterKey([string]$Key) { return ($Key -match '\|(Latenz|STUTTER)$') }

# Gespeicherte Referenz (Referenz.json im Datenordner, ältere Ablage PC-Diagnose-Referenz.json), sonst $null
function Get-SavedReference([string]$Path = '') {
    $cands = @()
    if ($Path) { $cands += $Path }
    if ($script:DataDir) { $cands += (Join-Path $script:DataDir 'Referenz.json'), (Join-Path $script:DataDir 'PC-Diagnose-Referenz.json') }
    foreach ($f in $cands) {
        if (-not $f -or -not (Test-Path -LiteralPath $f)) { continue }
        $j = Read-JsonFile $f
        if (-not $j) { continue }
        $w = ConvertTo-ValueTable $j.Werte
        if (-not $w.Count) { continue }
        $h = @{}
        if ($j.Herkunft) { foreach ($p in $j.Herkunft.PSObject.Properties) { $h[$p.Name] = [string]$p.Value } }
        return @{ Name = [string]$j.Name; Datum = [string]$j.Datum; Werte = $w; Herkunft = $h; Quelle = $f; Computer = [string]$j.Computer; GeraetId = [string]$j.GeraetId }
    }
    # Ab v3.0: Standard-Referenzprofil Desktop_Mittelklasse.json laden, wenn noch keine Referenz definiert ist
    if (-not $Path) {
        $defCands = @()
        if ($script:DbDir) { $defCands += (Join-Path $script:DbDir 'Desktop_Mittelklasse.json') }
        if ($script:DataDir) { $defCands += (Join-Path (Join-Path $script:DataDir 'Datenbank') 'Desktop_Mittelklasse.json') }
        foreach ($df in $defCands) {
            if (-not $df -or -not (Test-Path -LiteralPath $df)) { continue }
            $j = Read-JsonFile $df
            if (-not $j) { continue }
            $w = ConvertTo-ValueTable $j.Werte
            if (-not $w.Count) { continue }
            $h = @{}
            if ($j.Herkunft) { foreach ($p in $j.Herkunft.PSObject.Properties) { $h[$p.Name] = [string]$p.Value } }
            return @{ Name = [string]$j.Name; Datum = [string]$j.Datum; Werte = $w; Herkunft = $h; Quelle = $df; Computer = [string]$j.Computer; GeraetId = [string]$j.GeraetId }
        }
        if ($script:EmbeddedReferences -and $script:EmbeddedReferences.ContainsKey('Desktop_Mittelklasse.json')) {
            try {
                $j = $script:EmbeddedReferences['Desktop_Mittelklasse.json'] | ConvertFrom-Json
                if ($j) {
                    $w = ConvertTo-ValueTable $j.Werte
                    if ($w.Count) {
                        $h = @{}
                        if ($j.Herkunft) { foreach ($p in $j.Herkunft.PSObject.Properties) { $h[$p.Name] = [string]$p.Value } }
                        return @{ Name = [string]$j.Name; Datum = [string]$j.Datum; Werte = $w; Herkunft = $h; Quelle = 'Eingebettet (Desktop_Mittelklasse.json)'; Computer = [string]$j.Computer; GeraetId = [string]$j.GeraetId }
                    }
                }
            } catch { }
        }
    }
    return $null
}

function Import-BenchReference {
    $script:Ref = $script:RefNone
    if ($ReferenzDatei -eq '*median') {
        $entries = @(Get-DbLatest (Get-DbEntries) -ExcludeCurrent)
        if ($entries.Count) {
            $w = @{}
            $keys = @($entries | ForEach-Object { $_.Werte.Keys } | Select-Object -Unique)
            foreach ($k in $keys) { $m = Get-Median @($entries | ForEach-Object { $_.Werte[$k] } | Where-Object { $_ -gt 0 }); if ($m) { $w[$k] = [math]::Round($m, 1) } }
            $script:Ref = @{ Name = ('Median von {0} Systemen der Vergleichsdatenbank' -f $entries.Count); Datum = (Get-Date).ToString('yyyy-MM-dd', $script:Inv); Werte = $w; Herkunft = @{}; Quelle = 'Vergleichsdatenbank' }
            return
        }
        Add-Line '  Die Vergleichsdatenbank enthält noch keine anderen Systeme, daher gilt die gespeicherte Referenz.'
    }
    $r = Get-SavedReference $(if ($ReferenzDatei -and $ReferenzDatei -ne '*median') { $ReferenzDatei } else { '' })
    if ($r) { $script:Ref = $r }
}

# Gibt es eine Referenz mit Werten?
function Test-HasReference { return [bool]($script:Ref -and $script:Ref.Werte -and $script:Ref.Werte.Count) }

# Name einer Messgröße für Tabellen (Schlüssel wie CPU|ST oder DISK|NVMe4|SR)
function Get-MetricName([string]$Key) {
    $d = @($script:MetricDefs | Where-Object { $_.K -eq $Key }) | Select-Object -First 1
    if ($d) { return $d.N }
    if ($Key -match '^DISK\|([^|]+)\|(\w+)$') {
        $cls = $(if ($script:DiskClassNames.Contains($Matches[1])) { $script:DiskClassNames[$Matches[1]] } else { $Matches[1] })
        $kind = @{ SR = 'seq. lesen'; SW = 'seq. schreiben'; R1 = '4K zufällig QD1'; R8 = '4K zufällig 8 Threads'; W1 = '4K zufällig schreiben QD1' }[$Matches[2]]
        return ('{0} {1}' -f $cls, $(if ($kind) { $kind } else { $Matches[2] }))
    }
    return $Key
}

# Referenzwerte der in diesem Lauf verglichenen Messgrößen mit Herkunft
function Get-ReferenceRows {
    if (-not $script:Ref -or -not $script:Ref.Werte) { return @() }
    $keys = @($script:BenchResults | Where-Object { $_.RefKey -and $null -ne $_.RefPct } | ForEach-Object { $_.RefKey } | Select-Object -Unique)
    foreach ($k in $keys) {
        if (-not $script:Ref.Werte.ContainsKey($k)) { continue }
        $u = @($script:MetricDefs | Where-Object { $_.K -eq $k } | ForEach-Object { $_.U }) | Select-Object -First 1
        if (-not $u) { $u = $(if ($k -match '\|(SR|SW)$') { 'MB/s' } elseif ($k -like 'DISK|*') { 'IOPS' } else { '' }) }
        $v = [double]$script:Ref.Werte[$k]
        [pscustomobject][ordered]@{ Key = $k; 'Messgröße' = (Get-MetricName $k); Wert = $v; Referenz = ('{0} {1}' -f $(if ($v -ge 100) { '{0:N0}' -f $v } else { '{0:N1}' -f $v }), $u).Trim()
            Herkunft = $(if ($script:Ref.Herkunft -and $script:Ref.Herkunft.ContainsKey($k)) { [string]$script:Ref.Herkunft[$k] } else { [string]$script:Ref.Quelle }) }
    }
}

function Get-RefPct([string]$RefKey, [double]$Wert, [switch]$LowerBetter) {
    if (-not $RefKey -or -not $script:Ref -or -not $script:Ref.Werte.ContainsKey($RefKey)) { return $null }
    $r = [double]$script:Ref.Werte[$RefKey]
    if ($r -le 0 -or $Wert -le 0) { return $null }
    if ($LowerBetter) { return [int][math]::Round($r / $Wert * 100.0) }
    return [int][math]::Round($Wert / $r * 100.0)
}

function Get-StatusRank([string]$s) { switch ($s) { 'Fehler' { 3 } 'Warnung' { 2 } 'Info' { 1 } default { 0 } } }

function Get-GeoMean($Values, $Weights = $null) {
    if (-not $Values) { return $null }
    $valList = @($Values)
    $weightList = $(if ($Weights) { @($Weights) } else { $null })
    $s = 0.0
    $wSum = 0.0
    for ($i = 0; $i -lt $valList.Count; $i++) {
        $x = $valList[$i]
        if ($null -ne $x -and [double]$x -gt 0) {
            $w = $(if ($weightList -and $i -lt $weightList.Count -and $null -ne $weightList[$i] -and [double]$weightList[$i] -gt 0) { [double]$weightList[$i] } else { 1.0 })
            $s += $w * [math]::Log([double]$x)
            $wSum += $w
        }
    }
    if ($wSum -le 0) { return $null }
    return [int][math]::Round([math]::Exp($s / $wSum))
}

# Zusammenfassung einer Benchmark-Gruppe: schlechtester Status, Referenz-% (geometrisches Mittel), Kopfzeile
function Get-BenchGroup([string]$Gruppe) {
    $items = @($script:BenchResults | Where-Object { $_.Gruppe -eq $Gruppe })
    $disks = @()
    if ($Gruppe -eq 'Laufwerke') { $disks = @($script:BenchDisks) }
    $all = @($items) + @($disks)
    $st = 'OK'; foreach ($i in $all) { if ((Get-StatusRank $i.Status) -gt (Get-StatusRank $st)) { $st = $i.Status } }
    $ref = $(if ($Gruppe -eq 'Laufwerke') {
        Get-GeoMean ($disks | ForEach-Object { $_.RefPct })
    } elseif ($Gruppe -eq 'GPU') {
        $validItems = @($items | Where-Object { $null -ne $_.RefPct -and [double]$_.RefPct -gt 0 })
        if ($validItems.Count) {
            # Gemessene FPS-Renderleistung (Direct3D 11 Rendertest) erhält ein deutlich höheres Gewicht (3x) gegenüber theoretischen Werten
            $weights = @(foreach ($it in $validItems) {
                if ($it.Key -match 'REND|RPKT' -or $it.RefKey -match 'REND|RPKT') { 3.0 } else { 1.0 }
            })
            Get-GeoMean ($validItems | ForEach-Object { $_.RefPct }) $weights
        } else { $null }
    } else {
        Get-GeoMean ($items | ForEach-Object { $_.RefPct })
    })
    $head = [string]$script:BenchHead[$Gruppe]
    return [pscustomobject]@{ Gruppe = $Gruppe; Name = [string]$script:BenchGroupNames[$Gruppe]; Status = $st; RefPct = $ref
        Referenz = $(if ($null -ne $ref) { '{0} %' -f $ref } else { '' }); Kopf = $head; Anzahl = $all.Count; Items = $items; Disks = $disks }
}

# Gesamtbewertung über alle Gruppen (Prozessor und Grafik 2x gewichtet gegenüber RAM und Laufwerken)
function Get-BenchOverall {
    $weights = @{ 'CPU' = 2.0; 'GPU' = 2.0; 'RAM' = 1.0; 'Laufwerke' = 1.0 }
    $vals = [System.Collections.Generic.List[double]]::new()
    $w = [System.Collections.Generic.List[double]]::new()
    foreach ($gk in 'CPU', 'RAM', 'GPU', 'Laufwerke') {
        $g = Get-BenchGroup $gk
        if ($null -ne $g.RefPct -and [double]$g.RefPct -gt 0) {
            $vals.Add([double]$g.RefPct)
            $w.Add($weights[$gk])
        }
    }
    if (-not $vals.Count) { return $null }
    return Get-GeoMean $vals $w
}

# Bewertungswort für Benchmark-Werte in Prozent der Referenz (UserBenchmark-Stil)
function Get-BenchRatingWord($Pct) {
    if ($null -eq $Pct -or "$Pct" -eq '') { return '' }
    $p = [double]$Pct
    if ($p -ge 115) { return 'Hervorragend' }
    if ($p -ge 100) { return 'Sehr gut' }
    if ($p -ge 85)  { return 'Gut' }
    if ($p -ge 70)  { return 'Durchschnittlich' }
    if ($p -ge 50)  { return 'Mäßig' }
    return 'Unterdurchschnittlich'
}
function Get-Bewertungswort($Pct) { Get-BenchRatingWord $Pct }

function Send-BenchGroup([string]$Gruppe) {
    $g = Get-BenchGroup $Gruppe
    if ($g.Anzahl) { Send-GuiEvent 'BGRP' $Gruppe $g.Name $g.Status $g.Kopf $g.Referenz }
}

# Messwerte dieses Laufs als Referenzwerte (Laufwerke als Mittelwert je Klasse)
function Get-CurrentRefValues {
    $w = @{}
    foreach ($b in $script:BenchResults) { if ($b.RefKey -and $b.Wert -gt 0 -and $b.RefKey -notlike 'DISK|*') { $w[$b.RefKey] = [math]::Round([double]$b.Wert, 1) } }
    $byKey = @{}
    foreach ($b in $script:BenchResults) { if ($b.RefKey -like 'DISK|*' -and $b.Wert -gt 0) { if (-not $byKey.ContainsKey($b.RefKey)) { $byKey[$b.RefKey] = New-Object System.Collections.ArrayList }; [void]$byKey[$b.RefKey].Add([double]$b.Wert) } }
    foreach ($k in $byKey.Keys) { $w[$k] = [math]::Round((($byKey[$k] | Measure-Object -Average).Average), 0) }
    return $w
}

# Referenz speichern (Haken "Dieses System als Referenz festlegen"). Ist schon eine Referenz desselben Geräts gespeichert,
# bleiben deren Messgrößen erhalten, die dieser Lauf nicht gemessen hat (z. B. Benchmark nur mit CPU); ein anderes Gerät
# ersetzt die Referenz ganz. Herkunft je Messgröße für den Bericht.
function Save-BenchReference {
    $cur = Get-CurrentRefValues
    $dev = ''; try { $dev = [string](Get-DeviceIdentity).Id } catch { }
    $label = ('Lauf vom {0} (v{1})' -f (Get-Date).ToString('dd.MM.yyyy', $script:Inv), $ScriptVersion)
    $w = [ordered]@{}; $h = [ordered]@{}
    $old = Get-SavedReference
    $same = $old -and (($dev -and $old.GeraetId -eq $dev) -or ($old.Computer -and $old.Computer -eq $env:COMPUTERNAME))
    if ($same) { foreach ($k in @($old.Werte.Keys | Sort-Object)) { $w[$k] = $old.Werte[$k]; $h[$k] = $(if ($old.Herkunft.ContainsKey($k)) { $old.Herkunft[$k] } else { 'früherer Lauf' }) } }
    foreach ($k in @($cur.Keys | Sort-Object)) { $w[$k] = $cur[$k]; $h[$k] = $label }
    $o = [ordered]@{ Name = $(if ($script:BenchRefName) { $script:BenchRefName } else { [Environment]::MachineName }); Computer = $env:COMPUTERNAME; GeraetId = $dev; Datum = (Get-Date).ToString('yyyy-MM-dd', $script:Inv); Version = $ScriptVersion; Werte = $w; Herkunft = $h }
    $json = $o | ConvertTo-Json -Depth 4
    $saved = @()
    $targets = @()
    if ($script:DataDir) { $targets += (Join-Path $script:DataDir 'Referenz.json') }
    foreach ($f in $targets) {
        try { [IO.File]::WriteAllText($f, $json, (New-Object Text.UTF8Encoding($false))); $saved += $f } catch { }
    }
    return $saved
}

# Vergleich mit Systemen aus der Datenbank: eine Zeile je Messgröße
function Get-CompareRows {
    $cur = Get-CurrentRefValues
    $sys = @($script:CmpSystems)
    $latest = @(Get-DbLatest (Get-DbEntries) -ExcludeCurrent)
    $defs = [System.Collections.Generic.List[object]]::new()
    foreach ($d in $script:MetricDefs) { $defs.Add($d) }
    foreach ($cls in $script:DiskClassNames.Keys) {
        $has = $cur.ContainsKey("DISK|$cls|SR") -or @($sys | Where-Object { $_.Werte.ContainsKey("DISK|$cls|SR") }).Count
        if (-not $has) { continue }
        $cn = $script:DiskClassNames[$cls]
        $defs.Add(@{ K = "DISK|$cls|SR"; N = "$cn seq. lesen"; U = 'MB/s'; F = 'N0' })
        $defs.Add(@{ K = "DISK|$cls|SW"; N = "$cn seq. schreiben"; U = 'MB/s'; F = 'N0' })
        $defs.Add(@{ K = "DISK|$cls|R1"; N = "$cn 4K zufällig QD1"; U = 'IOPS'; F = 'N0' })
    }
    $rows = [System.Collections.Generic.List[object]]::new()
    foreach ($d in $defs) {
        $mine = $(if ($cur.ContainsKey($d.K)) { [double]$cur[$d.K] } else { $null })
        $vals = @($sys | ForEach-Object { if ($_.Werte.ContainsKey($d.K)) { [double]$_.Werte[$d.K] } else { $null } })
        if ($null -eq $mine -or -not @($vals | Where-Object { $null -ne $_ }).Count) { continue }
        $rank = ''
        if ($null -ne $mine) {
            $pool = @($latest | ForEach-Object { if ($_.Werte.ContainsKey($d.K)) { [double]$_.Werte[$d.K] } } | Where-Object { $_ -gt 0 })
            if ($pool.Count) {
                $better = @($pool | Where-Object { if ($d.L) { $_ -lt $mine } else { $_ -gt $mine } }).Count
                $rank = 'Platz {0} von {1}' -f ($better + 1), ($pool.Count + 1)
            }
        }
        $rows.Add([pscustomobject]@{ Key = $d.K; Messung = $d.N; Einheit = $d.U; Format = $d.F; LowerBetter = [bool]$d.L; Dieses = $mine; Werte = $vals; Rang = $rank })
    }
    return $rows.ToArray()
}

# Werte einer Vergleichszeile aufsteigend: "LIZZZ 21,3 GB/s < Dieser PC 57,4 GB/s < TORRENT 61,8 GB/s"
function Get-CompareOrderText($Row, [switch]$Gui) {
    $items = @([pscustomobject]@{ N = $(if ($Gui) { '▶ Dieser PC' } else { 'Dieser PC' }); V = $Row.Dieses; Own = $true })
    for ($k = 0; $k -lt $script:CmpSystems.Count; $k++) { if ($null -ne $Row.Werte[$k]) { $items += [pscustomobject]@{ N = $script:CmpSystems[$k].Computer; V = $Row.Werte[$k]; Own = $false } } }
    $items = @($items | Where-Object { $null -ne $_.V -and [double]$_.V -gt 0 } | Sort-Object { [double]$_.V })
    $txt = @($items | ForEach-Object { $rel = $(if (-not $_.Own) { Get-RelText $Row.Dieses $_.V $Row.LowerBetter } else { '' }); '{0} {1}{2}' -f $_.N, (Format-Metric $_.V $Row.Format $Row.Einheit), $(if ($rel) { ' (' + $rel + ')' } else { '' }) })
    return ($txt -join $(if ($Gui) { '  <  ' } else { ' < ' }))
}

function Format-Metric($Value, [string]$Fmt, [string]$Unit) {
    if ($null -eq $Value -or [double]$Value -le 0) { return '' }
    return ('{0:' + $Fmt + '} {1}') -f [double]$Value, $Unit
}

function Get-RelText($Mine, $Other, [bool]$LowerBetter) {
    if ($null -eq $Mine -or $null -eq $Other -or [double]$Mine -le 0 -or [double]$Other -le 0) { return '' }
    # positiv = das andere System ist besser
    $d = $(if ($LowerBetter) { ([double]$Mine / [double]$Other - 1) * 100 } else { ([double]$Other / [double]$Mine - 1) * 100 })
    return '{0:+0;-0;0} %' -f $d
}

# Skala der y-Achse (ab v2.8): runde Schritte mit so vielen Nachkommastellen, wie der Schritt braucht. Bis v2.7 wurden
# Schritte wie 0,5 ohne Nachkommastellen beschriftet (62, 62, 61, 61, 60). Ganzzahlige Messreihen (Temperatur in °C,
# Takt, Drehzahl) bekommen mindestens Schritt 1.
function Get-ChartScale([double]$Min, [double]$Max, [switch]$Integer) {
    $raw = ($Max - $Min) / 4; if ($raw -le 0) { $raw = [math]::Max(1.0, [math]::Abs($Max) * 0.05) }
    $mag = [math]::Pow(10, [math]::Floor([math]::Log10($raw)))
    $nice = $mag; foreach ($f in 1, 2, 2.5, 5, 10) { if ($Integer -and $f -eq 2.5 -and $mag -le 1) { continue }; if ($f * $mag -ge $raw - 1e-9) { $nice = $f * $mag; break } }
    if ($Integer -and $nice -lt 1) { $nice = 1.0 }
    $y0 = [math]::Floor($Min / $nice + 1e-9) * $nice; $y1 = [math]::Ceiling($Max / $nice - 1e-9) * $nice; if ($y1 -le $y0) { $y1 = $y0 + $nice }
    # Nachkommastellen nach dem Bruchteil des Schritts (0,5 eine, 0,25 und 2,5 bei 0,25 bzw. eine)
    $dec = 0
    while ($dec -lt 6 -and [math]::Abs([math]::Round($nice, $dec) - $nice) -gt 1e-9) { $dec++ }
    if ($dec -eq 0 -and [math]::Abs([math]::Round($y0, 0) - $y0) -gt 1e-9) { $dec = 1 }
    $ticks = New-Object System.Collections.Generic.List[double]
    $n = [int][math]::Round(($y1 - $y0) / $nice)
    for ($i = 0; $i -le $n; $i++) { $ticks.Add([math]::Round($y0 + $i * $nice, 6)) }
    return [pscustomobject]@{ Y0 = $y0; Y1 = $y1; Step = $nice; Format = ('N{0}' -f $dec); Ticks = $ticks.ToArray() }
}

# Beschriftungen der senkrechten Markierungen (Abschnitte, Lastende, Abbruch) ohne Überschneidung (ab v2.8): Breite
# geschätzt (11 px Schrift), jede Beschriftung in die erste Zeile, in der sie frei ist; am rechten Rand links der Linie.
# Rückgabe je Markierung X, Y, Anker (start|end) und Text.
function Get-ChartMarkLayout($Marks, [double]$Left, [double]$Right, [double]$Top, [scriptblock]$Fx, [double]$XMax, [int]$MaxLanes = 3) {
    $out = New-Object System.Collections.Generic.List[object]
    $lanes = @{}
    foreach ($m in @($Marks | Where-Object { $_ -and $null -ne $_.T -and [double]$_.T -ge 0 -and [double]$_.T -le $XMax } | Sort-Object { [double]$_.T })) {
        $x = & $Fx ([double]$m.T)
        $txt = [string]$m.Label
        $w = [math]::Ceiling($txt.Length * 6.3) + 4
        $anchor = 'start'; $a = $x + 4; $b = $a + $w
        if ($b -gt $Right) { $anchor = 'end'; $b = $x - 4; $a = $b - $w }
        if ($a -lt $Left) { $a = $Left; $b = $a + $w }
        $lane = -1
        for ($l = 0; $l -lt $MaxLanes; $l++) {
            $free = $true
            foreach ($iv in @($lanes[$l])) { if ($iv -and $a -lt $iv[1] + 6 -and $b + 6 -gt $iv[0]) { $free = $false; break } }
            if ($free) { $lane = $l; break }
        }
        if ($lane -lt 0) { $txt = ''; $lane = 0 } else { $lanes[$lane] = @($lanes[$lane]) + , @($a, $b) }
        $out.Add([pscustomobject]@{ LineX = $x; X = $(if ($anchor -eq 'end') { $x - 4 } else { $x + 4 }); Y = $Top + 11 + $lane * 13; Anchor = $anchor; Text = $txt; Label = [string]$m.Label })
    }
    return $out.ToArray()
}

function New-LineSvg($Points, [string]$Unit) {
    $inv = $script:Inv
    $pts = @($Points | Where-Object { $null -ne $_.V -and $_.V -gt 0 })
    if ($pts.Count -lt 2) { return '' }
    $W = 960; $H = 260; $ml = 70; $mr = 20; $mt = 14; $mb = 38
    $xmax = [double](($pts | Measure-Object T -Maximum).Maximum); if ($xmax -le 0) { $xmax = 1 }
    $vmin = [double](($pts | Measure-Object V -Minimum).Minimum); $vmax = [double](($pts | Measure-Object V -Maximum).Maximum)
    if ($Unit -eq 'Bilder/s' -or $Unit -eq 'FPS') { $vmin = 0.0 }
    if ($Unit -eq '%') { $vmin = 0.0; if ($vmax -lt 100) { $vmax = 100.0 } }
    $sc = Get-ChartScale $vmin $vmax -Integer:$(-not @($pts | Where-Object { [double]$_.V -ne [math]::Round([double]$_.V) }).Count)
    $y0 = $sc.Y0; $y1 = $sc.Y1
    $pw = $W - $ml - $mr; $ph = $H - $mt - $mb
    $fx = { param($t) $ml + $t / $xmax * $pw }
    $fy = { param($v) $mt + ($y1 - $v) / ($y1 - $y0) * $ph }
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append([string]::Format($inv, '<svg class="chart" viewBox="0 0 {0} {1}" role="img" preserveAspectRatio="xMidYMid meet">', $W, $H))
    foreach ($v in $sc.Ticks) {
        $y = & $fy $v
        [void]$sb.Append([string]::Format($inv, '<line class="grid" x1="{0}" x2="{1}" y1="{2:0.#}" y2="{2:0.#}"/>', $ml, $W - $mr, $y))
        [void]$sb.Append([string]::Format($inv, '<text x="{0}" y="{1:0.#}" text-anchor="end" dominant-baseline="middle">{2}</text>', $ml - 8, $y, $v.ToString($sc.Format, [Globalization.CultureInfo]::CurrentCulture)))
    }
    $tickS = 15
    foreach ($c in 15, 30, 60, 120, 300, 600, 900, 1800, 3600) { $tickS = $c; if ($xmax / $c -le 8) { break } }
    for ($t = 0; $t -le $xmax + 0.1; $t += $tickS) {
        $x = & $fx $t
        $lab = $(if ($tickS -ge 60) { '{0} min' -f [int]($t / 60) } else { '{0} s' -f [int]$t })
        [void]$sb.Append([string]::Format($inv, '<line class="tick" x1="{0:0.#}" x2="{0:0.#}" y1="{1}" y2="{2}"/><text x="{0:0.#}" y="{3}" text-anchor="middle">{4}</text>', $x, $mt + $ph, $mt + $ph + 5, $H - 12, $lab))
    }
    $poly = ($pts | ForEach-Object { [string]::Format($inv, '{0:0.#},{1:0.#}', (& $fx $_.T), (& $fy $_.V)) }) -join ' '
    [void]$sb.Append(('<polyline class="line" points="{0}"/>' -f $poly))
    $stepPts = [math]::Max(1, [int][math]::Ceiling($pts.Count / 300))
    for ($i = 0; $i -lt $pts.Count; $i += $stepPts) {
        $p = $pts[$i]
        $tl = '{0}:{1:00} min  ·  {2:N0} {3}' -f [int][math]::Floor($p.T / 60), [int]($p.T % 60), $p.V, $Unit
        [void]$sb.Append([string]::Format($inv, '<circle class="hit" cx="{0:0.#}" cy="{1:0.#}" r="6" data-tip="{2}"><title>{2}</title></circle>', (& $fx $p.T), (& $fy $p.V), (ConvertTo-HtmlText $tl)))
    }
    [void]$sb.Append('</svg>')
    return $sb.ToString()
}

# Mehrere Kurven in einem Diagramm (Lasttest): Serien @{ Name; Cls = 's1'..'s4'; Points = T/V }, Bezugslinien @{ V; Label; Cls = 'lim'|'tj' },
# Markierungen @{ T; Label } als senkrechte Linien (Lastende, Abbruch, Beginn der Drosselung). Leer, wenn keine Serie zwei Punkte hat.
function New-MultiLineSvg {
    param($Series, [string]$Unit, $RefLines = @(), $Marks = @(), [string]$Fmt = 'N0')
    $inv = $script:Inv
    $ser = @($Series | ForEach-Object { $s = $_; $p = @($s.Points | Where-Object { $null -ne $_.V -and -not [double]::IsNaN([double]$_.V) }); if ($p.Count -ge 2) { [pscustomobject]@{ Name = $s.Name; Cls = $s.Cls; Points = $p } } })
    if (-not $ser.Count) { return '' }
    $W = 960; $H = 250; $ml = 70; $mr = 20; $mt = 14; $mb = 38
    $allP = @($ser | ForEach-Object { $_.Points })
    $xmax = [double](($allP | Measure-Object T -Maximum).Maximum); if ($xmax -le 0) { $xmax = 1 }
    # Beschriftungen der Marken in einem eigenen Band über der Zeichenfläche (ab v2.8), damit sie keine Kurve verdecken
    $pw = $W - $ml - $mr
    $fx = { param($t) $ml + $t / $xmax * $pw }
    $markLay = @(Get-ChartMarkLayout $Marks $ml ($W - $mr) 0 $fx $xmax)
    $lanes = @($markLay | Where-Object { $_.Text } | ForEach-Object { [int](($_.Y - 11) / 13) } | Measure-Object -Maximum)
    if ($markLay.Count) { $band = 13 * ($(if ($lanes.Count -and $null -ne $lanes[0].Maximum) { [int]$lanes[0].Maximum } else { 0 }) + 1) + 4; $mt += $band; $H += $band }
    $vals = @($allP | ForEach-Object { [double]$_.V }) + @($RefLines | ForEach-Object { [double]$_.V })
    $vmin = [double](($vals | Measure-Object -Minimum).Minimum); $vmax = [double](($vals | Measure-Object -Maximum).Maximum)
    if ($Unit -eq 'Bilder/s' -or $Unit -eq 'FPS') { $vmin = 0.0 }
    if ($Unit -eq '%') { $vmin = 0.0; if ($vmax -lt 100) { $vmax = 100.0 } }
    $sc = Get-ChartScale $vmin $vmax -Integer:$(-not @($vals | Where-Object { $_ -ne [math]::Round($_) }).Count)
    $y0 = $sc.Y0; $y1 = $sc.Y1
    $pw = $W - $ml - $mr; $ph = $H - $mt - $mb
    $fx = { param($t) $ml + $t / $xmax * $pw }
    $fy = { param($v) $mt + ($y1 - $v) / ($y1 - $y0) * $ph }
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append('<p class="lgd">')
    foreach ($s in $ser) {
        $lastV = [double]$s.Points[$s.Points.Count - 1].V; $maxV = [double](($s.Points | Measure-Object V -Maximum).Maximum)
        [void]$sb.Append(('<span><i class="sw {0}"></i>{1} <small>max {2} {3}</small></span>' -f $s.Cls, (ConvertTo-HtmlText $s.Name), $maxV.ToString($Fmt, [Globalization.CultureInfo]::CurrentCulture), (ConvertTo-HtmlText $Unit)))
    }
    foreach ($r in $RefLines) { [void]$sb.Append(('<span><i class="sw {0}"></i>{1}</span>' -f $r.Cls, (ConvertTo-HtmlText $r.Label))) }
    [void]$sb.Append('</p>')
    [void]$sb.Append([string]::Format($inv, '<svg class="chart ml" viewBox="0 0 {0} {1}" role="img" preserveAspectRatio="xMidYMid meet">', $W, $H))
    foreach ($v in $sc.Ticks) {
        $y = & $fy $v
        [void]$sb.Append([string]::Format($inv, '<line class="grid" x1="{0}" x2="{1}" y1="{2:0.#}" y2="{2:0.#}"/>', $ml, $W - $mr, $y))
        [void]$sb.Append([string]::Format($inv, '<text x="{0}" y="{1:0.#}" text-anchor="end" dominant-baseline="middle">{2}</text>', $ml - 8, $y, $v.ToString($sc.Format, [Globalization.CultureInfo]::CurrentCulture)))
    }
    $tickS = 15
    foreach ($c in 15, 30, 60, 120, 300, 600, 900, 1800, 3600) { $tickS = $c; if ($xmax / $c -le 8) { break } }
    for ($t = 0; $t -le $xmax + 0.1; $t += $tickS) {
        $x = & $fx $t
        $lab = $(if ($tickS -ge 60) { '{0} min' -f [int]($t / 60) } else { '{0} s' -f [int]$t })
        [void]$sb.Append([string]::Format($inv, '<line class="tick" x1="{0:0.#}" x2="{0:0.#}" y1="{1}" y2="{2}"/><text x="{0:0.#}" y="{3}" text-anchor="middle">{4}</text>', $x, $mt + $ph, $mt + $ph + 5, $H - 12, $lab))
    }
    foreach ($m in $markLay) {
        [void]$sb.Append([string]::Format($inv, '<line class="mark" x1="{0:0.#}" x2="{0:0.#}" y1="{1}" y2="{2}"><title>{3}</title></line>', $m.LineX, $(if ($m.Text) { $m.Y - 10 } else { $mt }), $mt + $ph, (ConvertTo-HtmlText $m.Label)))
        if ($m.Text) { [void]$sb.Append([string]::Format($inv, '<text class="mk" x="{0:0.#}" y="{1}" text-anchor="{2}">{3}</text>', $m.X, $m.Y, $m.Anchor, (ConvertTo-HtmlText $m.Text))) }
    }
    foreach ($r in $RefLines) {
        $y = & $fy ([double]$r.V)
        [void]$sb.Append([string]::Format($inv, '<line class="{3}" x1="{0}" x2="{1}" y1="{2:0.#}" y2="{2:0.#}"><title>{4}</title></line>', $ml, $W - $mr, $y, $r.Cls, (ConvertTo-HtmlText $r.Label)))
    }
    foreach ($s in $ser) {
        $poly = ($s.Points | ForEach-Object { [string]::Format($inv, '{0:0.#},{1:0.#}', (& $fx $_.T), (& $fy ([double]$_.V))) }) -join ' '
        [void]$sb.Append(('<polyline class="line {0}" points="{1}"/>' -f $s.Cls, $poly))
        $stepPts = [math]::Max(1, [int][math]::Ceiling($s.Points.Count / 200))
        for ($i = 0; $i -lt $s.Points.Count; $i += $stepPts) {
            $p = $s.Points[$i]
            if ($p.Tip) {
                $tl = $p.Tip
            } else {
                $tl = '{0}:{1:00} min  ·  {2}: {3} {4}' -f [int][math]::Floor($p.T / 60), [int]($p.T % 60), $s.Name, ([double]$p.V).ToString($Fmt, [Globalization.CultureInfo]::CurrentCulture), $Unit
            }
            $cleanTitle = ($tl -replace '<[^>]+>', ' · ').Trim(' ·')
            [void]$sb.Append([string]::Format($inv, '<circle class="hit {3}" cx="{0:0.#}" cy="{1:0.#}" r="7" data-tip="{2}"><title>{4}</title></circle>', (& $fx $p.T), (& $fy ([double]$p.V)), (ConvertTo-HtmlText $tl), $s.Cls, (ConvertTo-HtmlText $cleanTitle)))
        }
    }
    [void]$sb.Append('</svg>')
    return $sb.ToString()
}

function Add-Line([string]$Text = '') { [void]$script:Report.AppendLine($Text) }

function Add-Section([string]$Title, [string]$Prefix = '') {
    Add-Line; Add-Line ('=' * 100); Add-Line ('  ' + $Title.ToUpper()); Add-Line ('=' * 100)
    Write-Host ''
    Write-Host ('[{0}] {1}>> {2}' -f (Get-Date -Format 'HH:mm:ss'), $Prefix, $Title) -ForegroundColor Cyan
}

function Add-Sub([string]$Title) { Add-Line; Add-Line (('--- {0} ' -f $Title).PadRight(100, '-')) }

function Out-Report {
    param([Parameter(ValueFromPipeline = $true)]$InputObject, [switch]$List)
    begin   { $buf = New-Object System.Collections.ArrayList }
    process { if ($null -ne $InputObject) { [void]$buf.Add($InputObject) } }
    end {
        if ($buf.Count -eq 0) { Add-Line '  (keine Einträge)'; return }
        if ($buf[0] -is [string]) { Add-Line (($buf | ForEach-Object { '  ' + $_ }) -join "`r`n"); return }
        if ($List) { $t = $buf | Format-List * | Out-String -Width 300 }
        elseif ($buf[0].PSObject.BaseObject -is [System.Management.Automation.PSCustomObject]) {
            # ohne ausdrückliche Spaltenliste zeigt Format-Table höchstens 10 Spalten
            $props = @($buf[0].PSObject.Properties | ForEach-Object { $_.Name })
            $t = $buf | Format-Table -Property $props -AutoSize -Wrap | Out-String -Width 400
        }
        else       { $t = $buf | Format-Table -AutoSize -Wrap | Out-String -Width 300 }
        Add-Line ($t.Trim("`r", "`n"))
    }
}

function Add-Finding {
    param([ValidateSet('KRITISCH', 'WARNUNG', 'INFO')][string]$Level, [string]$Area, [string]$Text)
    if ($script:FindKeys -and -not $script:FindKeys.Add(('{0}|{1}|{2}' -f $Level, $Area, $Text))) { return }
    $script:Findings.Add([pscustomobject]@{ Stufe = $Level; Bereich = $Area; Befund = $Text })
    Send-GuiEvent 'FIND' $Level $Area $Text
    $color = @{ KRITISCH = 'Red'; WARNUNG = 'Yellow'; INFO = 'DarkCyan' }[$Level]
    Write-Host ('    [{0}] {1}: {2}' -f $Level, $Area, $Text) -ForegroundColor $color
}

function Write-Step([string]$Text) { Write-Host ('[{0}]    {1}' -f (Get-Date -Format 'HH:mm:ss'), $Text) -ForegroundColor Gray }

function Invoke-Section {
    param(
        [Parameter(Position = 0, Mandatory = $true)][string]$Title,
        [Parameter(Position = 1, Mandatory = $true)][scriptblock]$Body,
        [switch]$Skippable
    )
    $script:StepNo++
    $total = [math]::Max((Get-PlannedSteps), $script:StepNo)
    Add-Section $Title ('[{0}/{1}] ' -f $script:StepNo, $total)
    Show-Overall $Title
    Hide-Sub
    $script:CpCurrent = $Title
    Write-Checkpoint 'START' ('[{0}/{1}] {2}' -f $script:StepNo, $total, $Title)
    $isSkippable = [bool]($Skippable -or ($Title -match '^(Updates|Test: Microsoft Defender|Test: SMART-Langtest|Test: Arbeitsspeicher \(Mustertest\)|Energie$|Test: Dateisystem und Systemdateien|Benchmark: (Prozessor|Grafik))'))
    if (Get-Command Send-GuiEvent -ErrorAction SilentlyContinue) { Send-GuiEvent 'SKIP_ALLOWED' $(if ($isSkippable) { '1' } else { '0' }) }
    if ($isSkippable -and (Get-Command Test-SkipRequested -ErrorAction SilentlyContinue) -and (Test-SkipRequested)) {
        if (Get-Command Send-StepSkipped -ErrorAction SilentlyContinue) { Send-StepSkipped $Title }
        Add-Line ('  ÜBERSPRUNGEN: Schritt durch Benutzer übersprungen.')
        if (Get-Command Add-TestResult -ErrorAction SilentlyContinue) { Add-TestResult $Title 'ÜBERSPRUNGEN' 'Schritt durch Benutzer übersprungen' }
        Add-Finding INFO 'Ablauf' ('Schritt "{0}" wurde auf Benutzeranforderung übersprungen.' -f $Title)
        Write-Checkpoint 'SKIP' ('{0} (übersprungen)' -f $Title)
        Save-Partial
        if (Get-Command Send-GuiEvent -ErrorAction SilentlyContinue) { Send-GuiEvent 'SKIP_ALLOWED' '0' }
        return
    }
    # Vor Abschnitten, bei denen ein Absturz am ehesten droht, den Zwischenstand sofort sichern (sonst gedrosselt)
    if ($Title -match '^(Lasttest|Benchmark|Test: (CPU|Arbeitsspeicher)|Reparatur|Optimierung)') { Save-Partial -Force }
    # Schneller Modus: exklusive Messungen warten auf die Hintergrundprüfungen
    try { Enter-SectionSchedule $Title } catch { }
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $wasSkipped = $false
    try { & $Body }
    catch {
        if ($isSkippable -and ($_.Exception -is [System.OperationCanceledException] -or $_.Exception.Message -match 'übersprungen')) {
            $wasSkipped = $true
            Send-StepSkipped $Title
            Add-Line ('  ÜBERSPRUNGEN: Schritt durch Benutzer übersprungen.')
            if (Get-Command Add-TestResult -ErrorAction SilentlyContinue) { Add-TestResult $Title 'ÜBERSPRUNGEN' 'Schritt durch Benutzer übersprungen' }
            Add-Finding INFO 'Ablauf' ('Schritt "{0}" wurde auf Benutzeranforderung übersprungen.' -f $Title)
            Write-Checkpoint 'SKIP' ('{0} (übersprungen)' -f $Title)
        } else {
            $ln = $(if ($_.InvocationInfo) { $_.InvocationInfo.ScriptLineNumber } else { 0 })
            Add-Line ('  FEHLER in diesem Abschnitt: {0} (Zeile {1})' -f $_.Exception.Message, $ln)
            Write-Warning ('{0}: {1}' -f $Title, $_.Exception.Message)
            Write-Checkpoint 'FEHLER' ('{0}: {1} (Zeile {2})' -f $Title, $_.Exception.Message, $ln)
            # sichtbar in Befunden und Tests, nicht nur in den Details: ein abgebrochener Abschnitt darf nicht wie ein leerer Bericht aussehen
            if ($null -ne $script:SectionErrors) { $script:SectionErrors.Add([pscustomobject]@{ Abschnitt = $Title; Meldung = $_.Exception.Message; Zeile = $ln }) }
            Add-Finding WARNUNG 'Ablauf' ('Abschnitt "{0}" wurde wegen eines Skriptfehlers abgebrochen: {1} (Zeile {2}). Details in Checkpoint.log und in der KI-Datei.' -f $Title, $_.Exception.Message, $ln)
        }
    }
    finally {
        if (Get-Command Send-GuiEvent -ErrorAction SilentlyContinue) { Send-GuiEvent 'SKIP_ALLOWED' '0' }
    }
    $sw.Stop()
    $script:Timings.Add([pscustomobject]@{ Abschnitt = $Title; Dauer = ('{0:hh\:mm\:ss}' -f $sw.Elapsed) })
    if (-not $wasSkipped) { Write-Checkpoint 'OK' ('{0} ({1:hh\:mm\:ss})' -f $Title, $sw.Elapsed) }
    try { Exit-SectionSchedule $Title } catch { }
    Save-Partial
}

# Statische WMI-Klassen (Hardware) nur einmal je Lauf abfragen
$script:CimCache = @{}
function Get-CimCached([string]$Class, [string]$Namespace = '') {
    $k = if ($Namespace) { "$Namespace`:$Class" } else { $Class }
    if (-not $script:CimCache.ContainsKey($k)) {
        if ($Namespace) {
            $script:CimCache[$k] = @(Get-CimInstance -Namespace $Namespace -ClassName $Class -ErrorAction SilentlyContinue)
        } else {
            $script:CimCache[$k] = @(Get-CimInstance -ClassName $Class -ErrorAction SilentlyContinue)
        }
    }
    return $script:CimCache[$k]
}

# Laufzeit seit dem Start lesbar (ab v2.8): "5 Std 21 Min", "3 Tage 2 Std", ohne "0 Tage"
function Format-Uptime([TimeSpan]$Span) {
    if ($Span.TotalMinutes -lt 1) { return 'unter 1 Min' }
    $p = @()
    if ($Span.Days -gt 0) { $p += ('{0} {1}' -f $Span.Days, $(if ($Span.Days -eq 1) { 'Tag' } else { 'Tage' })) }
    if ($Span.Hours -gt 0) { $p += ('{0} Std' -f $Span.Hours) }
    if ($Span.Days -lt 2 -and $Span.Minutes -gt 0) { $p += ('{0} Min' -f $Span.Minutes) }
    return ($p -join ' ')
}

# Ausgabe in UTF-8, gelesen als OEM-Codepage (ab v2.8): Neuere netsh-Meldungen kommen unter Windows 11 in UTF-8, auch wenn
# die Konsole OEM 850 nutzt ("ben├Âtigen" statt "benötigen"). Nur wenn die Rückwandlung gültiges UTF-8 ergibt und
# typische Fehlzeichen verschwinden, wird der Text ersetzt.
function Repair-Utf8AsOem([string]$Text) {
    if (-not $Text -or $Text -notmatch '[\u251C\u00D4\u00C3\u2502]') { return $Text }
    try {
        $b = $script:OemEnc.GetBytes($Text)
        $u = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($b)
        if ($u -ne $Text -and $u -notmatch '[\u251C\u2502]') { return $u }
    } catch { }
    return $Text
}

function Invoke-External {
    param([string]$File, [string]$Arguments = '', [int]$TimeoutSec = 600, [Text.Encoding]$Encoding = $script:OemEnc, [string]$Progress = '', [int]$ExpectedSec = 0)
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $File; $psi.Arguments = $Arguments
    $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    # Arbeitsordner = Anhang des Berichts: Dateien, die Werkzeuge ungefragt im aktuellen Ordner ablegen, landen nicht auf dem PC
    if ($RawDir -and (Test-Path -LiteralPath $RawDir)) { $psi.WorkingDirectory = $RawDir }
    $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
    $psi.StandardOutputEncoding = $Encoding; $psi.StandardErrorEncoding = $Encoding
    $p = New-Object System.Diagnostics.Process
    $p.StartInfo = $psi
    try { [void]$p.Start() } catch { return [pscustomobject]@{ ExitCode = -1; Output = ''; Error = $_.Exception.Message; TimedOut = $false } }
    $o = $p.StandardOutput.ReadToEndAsync(); $e = $p.StandardError.ReadToEndAsync()
    $sw = [Diagnostics.Stopwatch]::StartNew(); $timedOut = $false
    while (-not $p.WaitForExit(500)) {
        if ((Get-Command Test-SkipRequested -ErrorAction SilentlyContinue) -and (Test-SkipRequested)) {
            try { $p.Kill() } catch { }
            throw (New-Object System.OperationCanceledException 'Vom Benutzer übersprungen')
        }
        if ($Progress) {
            $st = 'läuft seit {0:hh\:mm\:ss}' -f $sw.Elapsed
            if ($ExpectedSec -gt 0) { Show-Sub $Progress ($st + ('   (üblich: ca. {0} Min.)' -f [math]::Ceiling($ExpectedSec / 60))) ([int]([math]::Min(99.0, $sw.Elapsed.TotalSeconds / $ExpectedSec * 100.0))) }
            else { Show-Sub $Progress $st }
            # ab v2.7: Sensoren des Benchmarks während WinSAT
            if ($script:BenchSens -and $script:BenchSens.On) { Add-BenchSensorSample }
        }
        if ($sw.Elapsed.TotalSeconds -ge $TimeoutSec) { $timedOut = $true; break }
    }
    if ($Progress) { Hide-Sub }
    if ($timedOut) { try { $p.Kill() } catch { } ; [void]$p.WaitForExit(5000) }
    $res = [pscustomobject]@{
        ExitCode = $(if ($timedOut) { -2 } else { $p.ExitCode })
        Output   = ($o.Result -replace "`0", '')
        Error    = ($e.Result -replace "`0", '')
        TimedOut = $timedOut
    }
    $p.Dispose()
    return $res
}

# Text in Zeilen von höchstens $Width Zeichen umbrechen (an Leerzeichen), für den Kopf des Textberichts
function Split-TextLines([string]$Text, [int]$Width = 94) {
    $out = New-Object System.Collections.Generic.List[string]
    $line = ''
    foreach ($w in @(([string]$Text) -split '\s+' | Where-Object { $_ })) {
        if ($line.Length -and ($line.Length + 1 + $w.Length) -gt $Width) { $out.Add($line); $line = $w }
        else { $line = $(if ($line.Length) { $line + ' ' + $w } else { $w }) }
    }
    if ($line.Length) { $out.Add($line) }
    return $out.ToArray()
}

function Format-Size($Bytes) {
    if ($null -eq $Bytes) { return '' }
    $b = [double]$Bytes
    if ($b -ge 1TB) { return '{0:N2} TB' -f ($b / 1TB) }
    if ($b -ge 1GB) { return '{0:N1} GB' -f ($b / 1GB) }
    if ($b -ge 1MB) { return '{0:N0} MB' -f ($b / 1MB) }
    return '{0:N0} KB' -f ($b / 1KB)
}

function Get-Ev([hashtable]$Filter, [int]$Max = 1000) {
    try { @(Get-WinEvent -FilterHashtable $Filter -MaxEvents $Max -ErrorAction SilentlyContinue) } catch { @() }
}

function Get-ShortText([string]$Text, [int]$Length = 160) {
    if (-not $Text) { return '' }
    $l = (($Text -split "`r?`n") | Where-Object { $_.Trim() } | Select-Object -First 1)
    if (-not $l) { return '' }
    $l = $l.Trim()
    if ($l.Length -gt $Length) { $l.Substring(0, $Length) + '...' } else { $l }
}

function Format-SizeDec($Bytes) {
    if ($null -eq $Bytes) { return '' }
    $b = [double]$Bytes
    if ($b -ge 1e12) { return '{0:N1} TB' -f ($b / 1e12) }
    if ($b -ge 1e9)  { return '{0:N0} GB' -f ($b / 1e9) }
    return '{0:N0} MB' -f ($b / 1e6)
}

function ConvertTo-HtmlText([string]$Text) {
    if ($null -eq $Text) { return '' }
    return (($Text -replace '&', '&amp;') -replace '<', '&lt;' -replace '>', '&gt;' -replace '"', '&quot;')
}

#region ---------- Schneller Modus: unabhängige Prüfungen parallel (ab v2.6, Roadmap v2.5) ----------
# Was parallel laufen darf, steht im Modulvertrag (Parallel = $true, Nach = Schritte, die vorher fertig sein müssen,
# Exklusiv = $true für Messungen). Im schnellen Modus starten diese Schritte als Hintergrundaufgaben in einem
# Runspace-Pool; die Abschnitte des Berichts bleiben in derselben Reihenfolge und holen dort nur das Ergebnis ab.
# Vor jeder exklusiven Messung (RAM-Test, Netzwerktest, Benchmark, Lasttest) warten alle Hintergrundaufgaben.
# Hintergrundaufgaben sind in sich geschlossene Skriptblöcke: Sie rufen keine Funktionen dieses Skripts auf.
$script:FastMode   = [bool]$SchnellerModus
$script:BgJobs     = [ordered]@{}
$script:BgPool     = $null
$script:BgDone     = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
$script:BgLastTick = [datetime]::MinValue
$script:BgAbandoned = 0   # abgebrochene Aufgaben, deren Runspace noch belegt sein kann

# Abhängigkeiten aus dem Modulvertrag: Key -> @{ Parallel; Exklusiv; Nach }
function Get-StepSchedule([string]$Module) {
    $res = @{}
    $c = Get-ModuleContract $Module
    if (-not $c) { return $res }
    foreach ($s in $c.Schritte) {
        $res[[string]$s.Key] = [pscustomobject]@{ Key = [string]$s.Key; Parallel = [bool]$s.Parallel; Exklusiv = [bool]$s.Exklusiv; Nach = @($s.Nach | Where-Object { $_ }) }
    }
    return $res
}

# Reihenfolge für den Start: ein Schritt startet erst, wenn alle Schritte unter Nach fertig sind (Kreise meldet Test-ModuleContract)
function Test-StepReady($Job) {
    foreach ($n in @($Job.Nach)) { if (-not $script:BgDone.Contains([string]$n)) { return $false } }
    return $true
}

function Initialize-BgPool {
    if ($script:BgPool) { return $true }
    try {
        $iss = [Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
        $script:BgPool = [runspacefactory]::CreateRunspacePool(1, 3, $iss, $Host)
        $script:BgPool.ApartmentState = 'STA'
        $script:BgPool.Open()
        return $true
    } catch { $script:BgPool = $null; Write-Checkpoint 'INFO' ('Schneller Modus nicht verfügbar: {0}' -f $_.Exception.Message); return $false }
}

# Aufgabe anmelden; sie startet, sobald ihre Abhängigkeiten fertig sind (Update-BgJobs)
function Register-BgJob {
    param([string]$Key, [string]$Title, [scriptblock]$Script, [object[]]$Arguments = @(), [string[]]$Nach = @(), [scriptblock]$OnStart = $null, [scriptblock]$OnDone = $null)
    if (-not $script:FastMode) { return $false }
    if (-not (Initialize-BgPool)) { return $false }
    $script:BgJobs[$Key] = [pscustomobject]@{ Key = $Key; Titel = $Title; Script = $Script; Args = @($Arguments); Nach = @($Nach | Where-Object { $_ }); OnStart = $OnStart; OnDone = $OnDone
        Status = 'wartet'; PS = $null; Handle = $null; Start = $null; Ende = $null; Ergebnis = @(); Fehler = '' }
    Send-GuiEvent 'PAR' $Key $Title 'wartet' ''
    Update-BgJobs -Force
    return $true
}

# Fertige Aufgaben abholen und wartende starten. Wird bei jedem Abschnitt und bei jeder Fortschrittsmeldung aufgerufen (billig).
function Update-BgJobs([switch]$Force) {
    if (-not $script:BgJobs.Count) { return }
    $now = Get-Date
    if (-not $Force -and ($now - $script:BgLastTick).TotalMilliseconds -lt 500) { return }
    $script:BgLastTick = $now
    foreach ($j in @($script:BgJobs.Values)) {
        if ($j.Status -eq 'läuft' -and $j.Handle -and $j.Handle.IsCompleted) {
            try {
                $out = $j.PS.EndInvoke($j.Handle)
                $j.Ergebnis = @($out | Where-Object { $null -ne $_ })
                if ($j.PS.Streams.Error.Count) { $j.Fehler = ($j.PS.Streams.Error | Select-Object -First 3 | ForEach-Object { $_.ToString() }) -join '; ' }
            } catch { $j.Fehler = $(if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message }) }
            try { $j.PS.Dispose() } catch { }
            $j.PS = $null; $j.Handle = $null
            $j.Ende = Get-Date
            $j.Status = $(if ($j.Fehler -and -not @($j.Ergebnis | Where-Object { $null -ne $_ }).Count) { 'Fehler' } else { 'fertig' })
            [void]$script:BgDone.Add($j.Key)
            if ($j.OnDone) { try { & $j.OnDone $j } catch { } }
            $dur = '{0:mm\:ss}' -f ($j.Ende - $j.Start)
            Send-GuiEvent 'PAR' $j.Key $j.Titel $j.Status $dur
            Write-Checkpoint 'PARALL' ('{0}: {1} nach {2}{3}' -f $j.Titel, $j.Status, $dur, $(if ($j.Fehler) { ' (' + $j.Fehler + ')' } else { '' }))
        }
    }
    foreach ($j in @($script:BgJobs.Values)) {
        if ($j.Status -ne 'wartet' -or -not (Test-StepReady $j)) { continue }
        try {
            if ($j.OnStart) { try { & $j.OnStart $j } catch { } }
            $ps = [powershell]::Create()
            $ps.RunspacePool = $script:BgPool
            [void]$ps.AddScript($j.Script.ToString())
            foreach ($a in $j.Args) { [void]$ps.AddArgument($a) }
            $j.PS = $ps; $j.Start = Get-Date; $j.Handle = $ps.BeginInvoke(); $j.Status = 'läuft'
            Send-GuiEvent 'PAR' $j.Key $j.Titel 'läuft' ''
            Write-Checkpoint 'PARALL' ('{0}: gestartet' -f $j.Titel)
        } catch { $j.Status = 'Fehler'; $j.Fehler = $_.Exception.Message; [void]$script:BgDone.Add($j.Key) }
    }
}

# Ist zu einem Schritt eine Hintergrundaufgabe angemeldet?
function Test-BgJob([string]$Key) { return [bool]($script:BgJobs.Contains($Key)) }

# Auf eine Aufgabe warten (mit Fortschritt) und sie zurückgeben. Nach Ablauf der Frist wird sie abgebrochen.
function Wait-BgJob([string]$Key, [string]$Activity = '', [int]$TimeoutSec = 3600) {
    if (-not $script:BgJobs.Contains($Key)) { return $null }
    $j = $script:BgJobs[$Key]
    $sw = [Diagnostics.Stopwatch]::StartNew()
    while ($j.Status -in 'wartet', 'läuft') {
        Update-BgJobs -Force
        if ($j.Status -notin 'wartet', 'läuft') { break }
        if ((Get-Command Test-SkipRequested -ErrorAction SilentlyContinue) -and (Test-SkipRequested)) {
            Stop-BgJob $j 'Vom Benutzer übersprungen'
            break
        }
        if ($Activity) { Show-Sub $Activity ('läuft im Hintergrund seit {0:mm\:ss}' -f $(if ($j.Start) { (Get-Date) - $j.Start } else { [TimeSpan]::Zero })) }
        if ($sw.Elapsed.TotalSeconds -ge $TimeoutSec) { Stop-BgJob $j ('nach {0} Minuten abgebrochen' -f [math]::Max(1, [int]($TimeoutSec / 60))); break }
        Start-Sleep -Milliseconds 400
    }
    if ($Activity) { Hide-Sub }
    return $j
}

# Aufgabe abbrechen, ohne zu warten: PowerShell.Stop() und Dispose() blockieren, solange ein COM- oder .NET-Aufruf
# läuft (z. B. eine hängende Updatesuche). BeginStop stößt das Ende nur an, das Objekt wird aufgegeben.
function Stop-BgJob($Job, [string]$Reason) {
    $j = $Job
    if ($j.Status -notin 'wartet', 'läuft') { return }
    $wasRunning = ($j.Status -eq 'läuft')
    if ($j.PS) { try { [void]$j.PS.BeginStop($null, $null) } catch { }; $script:BgAbandoned++ }
    $j.PS = $null; $j.Handle = $null; $j.Status = 'abgebrochen'; $j.Fehler = $Reason; $j.Ende = Get-Date
    [void]$script:BgDone.Add($j.Key)
    # OnDone auch hier: z. B. hebt die Energieanalyse die ausgesetzte Standby-Sperre wieder auf
    if ($wasRunning -and $j.OnDone) { try { & $j.OnDone $j } catch { } }
    Send-GuiEvent 'PAR' $j.Key $j.Titel 'abgebrochen' ''
    Write-Checkpoint 'PARALL' ('{0}: abgebrochen ({1})' -f $j.Titel, $Reason)
}

# Vor exklusiven Messungen: alle Hintergrundaufgaben abwarten
function Wait-BgAll([string]$Reason = '') {
    if (-not $script:BgJobs.Count) { return }
    $open = @($script:BgJobs.Values | Where-Object { $_.Status -in 'wartet', 'läuft' })
    if (-not $open.Count) { return }
    Write-Step ('Warte auf {0} Hintergrundprüfung(en), damit {1} ohne Nebenlast läuft ...' -f $open.Count, $(if ($Reason) { $Reason } else { 'die Messung' }))
    foreach ($j in $open) { [void](Wait-BgJob $j.Key ('Hintergrund: ' + $j.Titel) 3600) }
}

# Zeile für den Bericht: lief parallel, wie lange
function Get-BgNote($Job) {
    if (-not $Job) { return '' }
    $d = $(if ($Job.Start -and $Job.Ende) { '{0:mm\:ss}' -f ($Job.Ende - $Job.Start) } else { '?' })
    return ('  Schneller Modus: lief im Hintergrund parallel zu anderen Prüfungen (Dauer {0}{1}).' -f $d, $(if ($Job.Fehler) { ', Meldung: ' + $Job.Fehler } else { '' }))
}

function Stop-BgJobs {
    Update-BgJobs -Force
    foreach ($j in @($script:BgJobs.Values)) { Stop-BgJob $j 'beim Laufende abgebrochen' }
    # Pool nur schließen, wenn nichts mehr läuft; sonst blockiert Close(). Aufgegebene Aufgaben endet das Prozessende.
    if (-not $script:BgAbandoned) { try { if ($script:BgPool) { $script:BgPool.Close(); $script:BgPool.Dispose() } } catch { } }
    $script:BgPool = $null
}

# Schritt eines Abschnitts aus dem Titel (für Abhängigkeiten auf Abschnitte im Vordergrund und die Sperre vor Messungen)
function Get-SectionStepKey([string]$Title) {
    switch -Regex ($Title) {
        '^Test: Dateisystem und Systemdateien' { return 'Integritaet' }
        '^Test: Microsoft Defender' { return 'Defender' }
        '^Test: SMART-Langtest wird gestartet' { return 'SmartLang' }
        '^Test: Netzwerk' { return 'Netzwerk' }
        '^Test: Arbeitsspeicher' { return 'RamTest' }
        '^Energie$' { return 'Energieanalyse' }
        '^Ereignisprotokolle' { return 'Ereignisse' }
        '^Updates$' { return 'Updatesuche' }
        '^(Benchmark|Lasttest)' { return 'Messung' }
        default { return '' }
    }
}

# Haken für Invoke-Section: vor exklusiven Schritten warten, danach den Schritt als fertig markieren
function Enter-SectionSchedule([string]$Title) {
    if (-not $script:BgJobs.Count) { return }
    Update-BgJobs -Force
    $k = Get-SectionStepKey $Title
    if (-not $k) { return }
    $excl = ($k -eq 'Messung')
    if (-not $excl) { $sch = Get-StepSchedule 'Diagnose'; if ($sch.ContainsKey($k) -and $sch[$k].Exklusiv) { $excl = $true } }
    if ($excl) { Wait-BgAll ('"' + $Title + '"') }
}
function Exit-SectionSchedule([string]$Title) {
    $k = Get-SectionStepKey $Title
    if ($k -and $k -ne 'Messung' -and -not (Test-BgJob $k)) { [void]$script:BgDone.Add($k) }
    if ($script:BgJobs.Count) { Update-BgJobs -Force }
}

# Abhängigkeiten, die in diesem Lauf nicht vorkommen (nicht gewählt, Defender inaktiv), gelten als erfüllt
function Get-ActiveDeps([string[]]$Nach) {
    return @(@($Nach) | Where-Object { $_ -and $script:Opt[$_] -and ($_ -ne 'Defender' -or $script:DefenderActive) -and ($_ -ne 'SmartLang' -or ($script:Smartctl -and @($script:SmartDevices).Count)) })
}

# Hintergrundaufgaben des Moduls Diagnose anmelden, sobald ihre Voraussetzungen bekannt sind:
#   Start     zu Beginn des Moduls (Updatesuche)
#   Defender  nach dem Abschnitt Sicherheit (Defender aktiv?), dazu die Energieanalyse (wartet laut Vertrag auf Defender)
#   SMART     nach dem Abschnitt SMART-Daten (Laufwerke bekannt)
function Start-DiagnoseParallel([string]$Phase) {
    if (-not $script:FastMode -or -not $ModDiag -or $AnalyzeLastRun -or $Kurztest) { return }
    $sch = Get-StepSchedule 'Diagnose'
    $n = 0
    switch ($Phase) {
        'Start' {
            if ($script:Opt['Updatesuche'] -and $sch['Updatesuche'].Parallel) {
                $n += [int](Register-BgJob -Key 'Updatesuche' -Title 'Suche nach ausstehenden Updates' -Nach (Get-ActiveDeps $sch['Updatesuche'].Nach) -Script {
                    $s = New-Object -ComObject Microsoft.Update.Session
                    $r = $s.CreateUpdateSearcher().Search("IsInstalled=0 and IsHidden=0")
                    foreach ($u in $r.Updates) { [pscustomobject]@{ Titel = $u.Title; KB = ($u.KBArticleIDs -join ','); Pflicht = $u.IsMandatory; Neustart = $u.RebootRequired } }
                })
            }
        }
        'Defender' {
            if ($script:Opt['Defender'] -and $script:DefenderActive -and $sch['Defender'].Parallel) {
                $n += [int](Register-BgJob -Key 'Defender' -Title 'Defender Schnellscan' -Nach (Get-ActiveDeps $sch['Defender'].Nach) -Script {
                    $t0 = Get-Date
                    Update-MpSignature -ErrorAction SilentlyContinue
                    Start-MpScan -ScanType QuickScan -ErrorAction Stop
                    [pscustomobject]@{ Start = $t0; Ende = (Get-Date) }
                })
            }
            if ($script:Opt['Energieanalyse'] -and $sch['Energieanalyse'].Parallel) {
                $html = Join-Path $RawDir 'Energiebericht.html'; $dx = Join-Path $RawDir 'dxdiag.txt'
                # eigene Standby-Sperre während der Energieanalyse aussetzen, damit sie nicht im Energiebericht erscheint
                $n += [int](Register-BgJob -Key 'Energieanalyse' -Title 'Energieanalyse und DxDiag' -Nach (Get-ActiveDeps $sch['Energieanalyse'].Nach) -Arguments @($html, $dx, $script:OemEnc.CodePage, "$env:windir\System32\dxdiag.exe") `
                    -OnStart { Suspend-StandbyLock } -OnDone { Resume-StandbyLock } -Script {
                    param($Html, $Dx, $Oem, $DxExe)
                    $psi = New-Object Diagnostics.ProcessStartInfo 'powercfg.exe', ('/energy /output "{0}" /duration 60' -f $Html)
                    $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true; $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
                    try { $psi.StandardOutputEncoding = [Text.Encoding]::GetEncoding($Oem) } catch { }
                    $p = [Diagnostics.Process]::Start($psi)
                    $o = $p.StandardOutput.ReadToEndAsync(); $e = $p.StandardError.ReadToEndAsync()
                    if (-not $p.WaitForExit(180000)) { try { $p.Kill() } catch { } }
                    $res = [pscustomobject]@{ Output = $o.Result; Error = $e.Result; ExitCode = $(try { $p.ExitCode } catch { -1 }); DxDiag = $false }
                    try {
                        $d = Start-Process -FilePath $DxExe -ArgumentList ('/t "{0}"' -f $Dx) -WindowStyle Hidden -PassThru
                        if (-not $d.WaitForExit(240000)) { try { $d.Kill() } catch { } }
                    } catch { }
                    $res.DxDiag = (Test-Path -LiteralPath $Dx)
                    $res
                })
            }
        }
        'SMART' {
            if ($script:Opt['SmartLang'] -and $script:Smartctl -and @($script:SmartDevices).Count -and $sch['SmartLang'].Parallel) {
                $devs = @($script:SmartDevices | ForEach-Object { [pscustomobject]@{ name = $_.name; type = $_.type } })
                $n += [int](Register-BgJob -Key 'SmartLang' -Title 'SMART-Langtest starten' -Nach (Get-ActiveDeps $sch['SmartLang'].Nach) -Arguments @($script:Smartctl, $devs) -Script {
                    param($Exe, $Devs)
                    foreach ($d in $Devs) {
                        $psi = New-Object Diagnostics.ProcessStartInfo $Exe, ('-t long -d {0} {1}' -f $d.type, $d.name)
                        $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true; $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
                        $t = Get-Date
                        $p = [Diagnostics.Process]::Start($psi)
                        $o = $p.StandardOutput.ReadToEndAsync(); $e = $p.StandardError.ReadToEndAsync()
                        if (-not $p.WaitForExit(60000)) { try { $p.Kill() } catch { } }
                        [pscustomobject]@{ Name = $d.name; Start = $t; Output = $o.Result; Error = $e.Result; ExitCode = $(try { $p.ExitCode } catch { -1 }) }
                    }
                })
            }
        }
    }
    if ($n) {
        $names = @($script:BgJobs.Values | Where-Object { $_.Status -in 'wartet', 'läuft' } | ForEach-Object { $_.Titel }) -join ', '
        Write-Step ('Schneller Modus: im Hintergrund laufen jetzt {0}. Messungen warten darauf.' -f $names)
    }
}
