    'BlackSharp.Core.dll'                        = @{ SHA256 = 'cafb93afcc8d8a367e21f619673d05c06887d8964867fed1371f02ded1cd3e23'; Lizenz = 'siehe THIRD-PARTY-NOTICES von LibreHardwareMonitor' }
